const WORKS = [{"id":"001","nr":"NV-001","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#a94a46","pal":["#8db7a2","#f00101","#ef1207","#6f5d64","#ba0a0c"],"p":2,"t":"Archipel in Rood","d":"Rode vlakken liggen als eilanden in een zee van turquoise en zacht oranje, gescheiden door smalle, lichte kustlijnen. Het oog reist van het een naar het ander zonder ergens tot stilstand te komen. Een werk dat warmte uitstraalt en tegelijk ruimte laat.","own":false,"e":"Red planes lie like islands in a sea of turquoise and soft orange, divided by narrow, pale coastlines. The eye travels from one to the next without ever coming to rest. A work that radiates warmth while still leaving room to breathe.","x":"Er zijn plekken waar je nooit bent geweest en die toch vertrouwd voelen. Dit is zo'n plek: een archipel van warmte waar het oog mag aanmeren, telkens op een ander eiland, telkens even thuis.","xe":"There are places you have never been that still feel familiar. This is one: an archipelago of warmth where the eye may come ashore, each time on a different island, each time briefly at home."},{"id":"002","nr":"NV-002","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#a3354a","pal":["#eb0805","#216ec1","#cb090c","#bc8890","#6c4670"],"p":2,"t":"Energy","d":"Energie kent vele vormen, en hier slaat ze over als een vonk. Rood en kobalt botsen, witte strepen flitsen erdoorheen als bliksem: de onzichtbare kracht die door ons allen heen beweegt, zichtbaar gemaakt. Rauw, elektrisch en levend, zoals Nanny zelf. Een werk voor de plek waar u een vonk nodig heeft.","own":true,"e":"Energy takes many forms, and here it arcs across like a spark. Red and cobalt collide, white streaks flash through them like lightning: the invisible force that moves through all of us, made visible. Raw, electric and alive, like Nanny herself. A work for the place where you need a spark.","x":"Sommige dagen heb je iets nodig dat je wakker schudt. Dit werk doet dat elke ochtend opnieuw: het herinnert eraan dat er een stroom door ons heen loopt, ook op de dagen dat we hem niet voelen.","xe":"Some days you need something to wake you. This work does so every morning anew: it reminds you that a current runs through us, even on the days we cannot feel it."},{"id":"003","nr":"NV-003","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#895751","pal":["#e00b03","#39778f","#d0c860","#7a1a2e","#55b8ad"],"p":3,"t":"Hoogzomer","d":"Rood, geel en turquoise vloeien in grote, ronde vormen in elkaar over, alsof de hitte van een zomermiddag op het doek is gesmolten. Er is geen horizon, alleen licht en kleur. Een werk dat een kamer verwarmt zonder te overheersen.","own":false,"e":"Red, yellow and turquoise flow into one another in large rounded forms, as if the heat of a summer afternoon had melted onto the canvas. There is no horizon, only light and colour. A work that warms a room without overwhelming it.","x":"Het is de middag die je je later blijft herinneren, zonder te weten waarom. Te warm om iets te doen, te mooi om binnen te blijven. Dat gevoel van tijd die even stilstaat, hangt hier aan de muur.","xe":"It is the afternoon you keep remembering later, without knowing why. Too warm to do anything, too beautiful to stay inside. That feeling of time standing still for a moment hangs here on the wall."},{"id":"004","nr":"NV-004","thema":"abstract","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#ca5256","pal":["#f7c2a8","#f0010c","#f11824","#b50a13","#8c7187"],"p":3,"t":"Feniks","d":"Uit een wolk van roze en blauw rijst een rode gestalte op, met één waakzaam oog. Half vogel, half verschijning: de vorm ontsnapt aan een vaste betekenis. Speels in uitvoering, maar met een raadselachtige ondertoon.","own":false,"e":"A red figure rises from a cloud of pink and blue, one watchful eye open. Half bird, half apparition, the form resists a fixed meaning. Playful in execution, with an enigmatic undertone.","x":"Wat valt, kan opnieuw opstaan. Dat is de belofte van de feniks, en ook van dit doek: iets dat zich losmaakt uit de nevel en de ogen opslaat. Voor wie weet hoe het is om opnieuw te beginnen.","xe":"What falls can rise again. That is the promise of the phoenix, and of this canvas too: something breaking free from the haze and opening its eyes. For anyone who knows what it is to begin again."},{"id":"005","nr":"NV-005","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":0.9583,"avg":"#ca0c17","pal":["#e7020b","#b20207","#d31026","#d33544","#bb0711"],"p":4,"t":"Binnenkamer","d":"Laag over laag rood, met een donkere kern die als een raam naar binnen opent. Hoe langer je kijkt, hoe meer tinten zich aandienen: karmijn, roze, bijna zwart. Een ingetogen, intens werk, onderaan gesigneerd.","own":false,"e":"Layer upon layer of red, with a dark core that opens like a window inward. The longer you look, the more shades emerge: carmine, pink, almost black. A restrained and intense work, signed at the bottom.","x":"Iedereen heeft een kamer waar niemand anders komt. Dit werk lijkt die ruimte te kennen: warm, besloten, met een donkere kern die niet eng is maar veilig. Hoe langer je kijkt, hoe meer het je toelaat.","xe":"Everyone has a room no one else enters. This work seems to know that space: warm, enclosed, with a dark core that feels not frightening but safe. The longer you look, the further it lets you in."},{"id":"006","nr":"NV-006","thema":"abstract","kleur":["blauw","oranje"],"ori":"vierkant","type":"enkel","ar":0.9618,"avg":"#4d434d","pal":["#0d608d","#042557","#b45f20","#932310","#6f6a6a"],"p":4,"t":"Blauw Interieur","d":"Blauw, roest en oker bouwen zich op tot een ruimte van vlakken en doorkijkjes, als een kamer die je vanuit verschillende hoeken tegelijk ziet. Het werk heeft de rust en het gewicht van architectuur. Een stille aanwezigheid aan de wand.","own":false,"e":"Blue, rust and ochre build into a space of planes and glimpses, like a room seen from several angles at once. The work has the calm and weight of architecture. A quiet presence on the wall.","x":"Er is troost in ruimte die klopt. Vlakken die elkaar dragen, licht dat ergens binnenvalt, een kamer waarin je even niets hoeft. Het werk geeft wat een goed huis ook geeft: rust zonder leegte.","xe":"There is comfort in a space that feels right. Planes that hold one another, light falling in from somewhere, a room in which, for a moment, nothing is asked of you. The work gives what a good home gives: calm without emptiness."},{"id":"007","nr":"NV-007","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":0.9754,"avg":"#9c1614","pal":["#bd0101","#9d0101","#990b09","#7f2e27","#8a5c56"],"p":4,"t":"Gevel in Rood","d":"Rode en zilvergrijze rechthoeken stapelen zich op als de gevel van een oude stad, verweerd en vol geschiedenis. De verf is op plekken weggeschraapt, zodat onderliggende lagen doorschemeren. Linksonder gesigneerd.","own":false,"e":"Red and silver-grey rectangles stack up like the façade of an old city, weathered and full of history. In places the paint has been scraped away, letting earlier layers show through. Signed lower left.","x":"Een gevel vertelt wat er achter de muren is geleefd. Hier schemeren oude lagen door het rood, zoals herinneringen door een gezicht. Niets is gewist; alles is gebleven, alleen zachter geworden.","xe":"A facade tells of the lives lived behind its walls. Here older layers glimmer through the red, as memories show in a face. Nothing has been erased; everything has stayed, only grown softer."},{"id":"008","nr":"NV-008","thema":"abstract","kleur":["blauw"],"ori":"vierkant","type":"enkel","ar":0.9754,"avg":"#328abb","pal":["#027bba","#81a9bf","#209ad1","#0b6bae","#357da8"],"p":4,"t":"Colonnade","d":"Verticale banen hemelsblauw, onderbroken door zilverachtige accenten, staan naast elkaar als zuilen in het middaglicht. Helder en fris, met een ritme dat een ruimte optilt. Bijzonder mooi tegen een warme wand.","own":false,"e":"Vertical bands of sky blue, interrupted by silvery accents, stand side by side like columns in midday light. Clear and fresh, with a rhythm that lifts a room. Particularly beautiful against a warm wall.","x":"Sommige ruimtes maken je rechter, alsof de lucht er hoger is. Dit werk heeft die kracht. Het ademt, het staat, het tilt een kamer op, en jou een beetje mee.","xe":"Some spaces make you stand a little straighter, as if the air were higher there. This work has that power. It breathes, it stands, it lifts a room, and you a little with it."},{"id":"009","nr":"NV-009","thema":"stad","kleur":["zwart","blauw"],"ori":"vierkant","type":"enkel","ar":0.962,"avg":"#38464c","pal":["#5dadc3","#09080a","#2c1a1c","#5b4d4d","#120f11"],"p":5,"t":"Het Blauwe Uur","d":"Zwarte silhouetten van gebouwen tekenen zich af tegen een turquoise lucht, met daartussen een gloed van oranje en roze. Het is het moment waarop de stad het licht aanknipt en de dag overgaat in de avond.","own":false,"e":"Black silhouettes of buildings stand out against a turquoise sky, with a glow of orange and pink in between. It is the moment the city switches on its lights and day gives way to evening.","x":"Het blauwe uur duurt maar even: de stad houdt haar adem in tussen dag en nacht. Wie dat moment kent, weet dat het nooit lang genoeg duurt. Hier blijft het, avond na avond.","xe":"The blue hour lasts only a moment: the city holds its breath between day and night. Whoever knows that moment knows it never lasts long enough. Here it stays, evening after evening."},{"id":"010","nr":"NV-010","thema":"abstract","kleur":["blauw","rood"],"ori":"liggend","type":"enkel","ar":1.2098,"avg":"#6b5660","pal":["#bf110d","#3e6984","#2d2b72","#c1c274","#40a38d"],"p":6,"t":"Maalstroom","d":"Ringen in alle kleuren van het spectrum cirkelen om een stralend blauw hart. Het werk trekt de blik onweerstaanbaar naar het midden, als een draaikolk van licht. Hypnotiserend, en een middelpunt in elke ruimte.","own":false,"e":"Rings in every colour of the spectrum circle a radiant blue heart. The work draws the eye irresistibly to its centre, like a whirlpool of light. Hypnotic, and a focal point in any room.","x":"Alles cirkelt, en toch is er een midden dat stil blijft. Misschien is dat het geheim van een leven: dat je, hoe hard het om je heen ook draait, een kern hebt die helder blijft.","xe":"Everything circles, and yet there is a centre that stays still. Perhaps that is the secret of a life: that however fast the world turns around you, you carry a core that stays clear."},{"id":"011","nr":"NV-011","thema":"abstract","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.6787,"avg":"#d36d4f","pal":["#c1b4a1","#ef0a04","#fbad55","#f75315","#9c263b"],"p":6,"t":"Dans in Rood","d":"Rood en oranje wervelen over een zachte grond van perzik en turquoise, met de lichtheid van een beweging die net is ingezet. Er is geen begin en geen eind, alleen een doorgaande stroom. Opgewekt zonder luidruchtig te zijn.","own":false,"e":"Red and orange swirl across a soft ground of peach and turquoise, with the lightness of a movement just begun. There is no beginning and no end, only a continuous flow. Joyful without being loud.","x":"Dit is het gevoel van dansen wanneer niemand kijkt. Geen pas is verkeerd, geen beweging hoeft ergens heen. Het werk vraagt niets van u, behalve dat u zich even mee laat nemen.","xe":"This is the feeling of dancing when no one is watching. No step is wrong, no movement has to lead anywhere. The work asks nothing of you, except that you let yourself be carried along for a while."},{"id":"012","nr":"NV-012","thema":"abstract","kleur":["rood","blauw"],"ori":"staand","type":"enkel","ar":0.6335,"avg":"#a35049","pal":["#e10000","#587184","#bdb276","#e51004","#91132a"],"p":7,"t":"Opbloei","d":"Op dit staande doek schieten rood, blauw en geel omhoog als bloemen die zich naar het licht strekken. De verticale compositie geeft het werk een opwaartse beweging. Ideaal voor een smalle wand of naast een raam.","own":false,"e":"On this vertical canvas red, blue and yellow shoot upward like flowers reaching for the light. The upright composition gives the work an ascending movement. Ideal for a narrow wall or beside a window.","x":"Alles wat leeft, zoekt het licht. Ook wij, na een lange winter of een zware tijd. Dit doek groeit omhoog met een vanzelfsprekendheid die hoop geeft.","xe":"Everything that lives seeks the light. So do we, after a long winter or a difficult time. This canvas grows upward with a self-evidence that gives hope."},{"id":"013","nr":"NV-013","thema":"abstract","kleur":["zwart","blauw"],"ori":"vierkant","type":"enkel","ar":1.0044,"avg":"#686471","pal":["#20191b","#484351","#808091","#c6b7c4","#abb5c8"],"p":8,"t":"Lavendelklif","d":"Lila en grijs rijzen op als een rotswand tegen diep zwart, met hier en daar een spoor van oker. De verf is breed en zelfverzekerd opgezet. Monumentaal en stil, een werk dat ruimte vraagt en geeft.","own":false,"e":"Lilac and grey rise like a cliff face against deep black, with an occasional trace of ochre. The paint is laid down broadly and confidently. Monumental and still, a work that asks for space and gives it in return.","x":"Er is een stilte die alleen bergen kennen. Groot, oud, onverschillig voor haast. Wie ervoor staat, wordt vanzelf kleiner, en vreemd genoeg ook rustiger.","xe":"There is a silence only mountains know. Vast, ancient, indifferent to hurry. Whoever stands before it grows smaller, and, strangely, calmer too."},{"id":"014","nr":"NV-014","thema":"abstract","kleur":["geel","zwart"],"ori":"liggend","type":"enkel","ar":1.6678,"avg":"#847a65","pal":["#746c80","#2c243e","#978d7e","#c0b373","#eddf43"],"p":8,"t":"Lichtval","d":"Een felgele vorm zweeft over violet en grijs, als zonlicht dat onverwacht door een wolkendek breekt. Eén lichtpunt in een koel, bijna nachtelijk landschap. Het contrast maakt het geel des te stralender.","own":false,"e":"A bright yellow form floats over violet and grey, like sunlight breaking unexpectedly through cloud. One point of light in a cool, almost nocturnal landscape. The contrast makes the yellow all the more radiant.","x":"Soms breekt het licht door op het moment dat je het niet meer verwacht. Eén plek van goud in een koele wereld is genoeg. Dit werk is gemaakt voor de dagen waarop u dat nodig heeft.","xe":"Sometimes the light breaks through just when you no longer expect it. One patch of gold in a cool world is enough. This work is made for the days when you need that."},{"id":"015","nr":"NV-015","thema":"abstract","kleur":["blauw","zwart"],"ori":"staand","type":"enkel","ar":0.6064,"avg":"#465c7b","pal":["#271220","#25345b","#6fa6cb","#4f7ea7","#91b6c9"],"p":9,"t":"Passage","d":"Een smalle blauwe ruimte waarin het licht van boven valt en langs de wanden naar beneden glijdt. Het werk gaat over diepte en stilte, over het moment voordat je een drempel overgaat. Bijzonder op een smalle wand.","own":false,"e":"A narrow blue space in which light falls from above and slides down the walls. The work is about depth and silence, about the moment before crossing a threshold. Especially fine on a narrow wall.","x":"Elke drempel vraagt moed, ook de kleine. Dit werk staat in dat ogenblik ervoor: het licht valt al naar binnen, de stap moet nog worden gezet. Een stille begeleider voor wie iets nieuws begint.","xe":"Every threshold asks for courage, even the small ones. This work stands in the moment before: the light is already falling in, the step has yet to be taken. A quiet companion for anyone beginning something new."},{"id":"016","nr":"NV-016","thema":"abstract","kleur":["geel","paars"],"ori":"vierkant","type":"enkel","ar":1.0102,"avg":"#ac9f7f","pal":["#f1e6d8","#342a4b","#a0948e","#f8e53c","#e6d896"],"p":9,"t":"Doorbraak","d":"Een geel vlak breekt door lagen crème, wit en diep violet, krachtig en onverwacht. De ruwe, geschraapte textuur contrasteert met de heldere kleur. Rechtsonder gesigneerd.","own":false,"e":"A yellow plane breaks through layers of cream, white and deep violet, forceful and unexpected. The rough, scraped texture contrasts with the clarity of the colour. Signed lower right.","x":"Er komt een moment waarop iets niet langer binnen te houden is. Een gedachte, een besluit, een kleur. Dit doek is dat moment: het geel dat zich niet meer laat bedekken.","xe":"There comes a moment when something can no longer be held in. A thought, a decision, a colour. This canvas is that moment: the yellow that will no longer stay covered."},{"id":"017","nr":"NV-017","thema":"abstract","kleur":["blauw","rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#556278","pal":["#6a0d08","#1298ce","#4aa4cd","#693f48","#92a8b5"],"p":10,"t":"Zonder Structuur","d":"Lichtblauwe vlakken kantelen over een vurig rode ondergrond, alsof de compositie elk moment kan verschuiven. Nanny's eigen titel speelt met die onrust. Een werk vol spanning tussen koel en warm.","own":true,"e":"Light blue planes tilt over a fiery red ground, as though the composition might shift at any moment. Nanny's own title plays with that restlessness. A work full of tension between cool and warm.","x":"Niet alles hoeft vast te liggen om goed te zijn. Misschien is dat precies de vrijheid die dit werk uitstraalt: rust vinden in wat beweegt, en vertrouwen in wat nog kan verschuiven.","xe":"Not everything has to be fixed to be good. Perhaps that is exactly the freedom this work radiates: finding calm in what moves, and trust in what may still shift."},{"id":"018","nr":"NV-018","thema":"abstract","kleur":["rood","zwart"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#75121a","pal":["#b80308","#2d0706","#b72635","#2e0e11","#432538"],"p":10,"t":"Doos van Pandora","d":"Dieprode vlakken openen zich als een deksel, met donkere schaduwen in de kieren. Wat erin zit, blijft verborgen. Nanny's titel verwijst naar de mythe van de doos die beter dicht had kunnen blijven: spannend, gelaagd en vol diepte.","own":true,"e":"Deep red planes open like a lid, with dark shadows in the gaps. What lies within stays hidden. Nanny's title refers to the myth of the box that might better have stayed closed: suspenseful, layered and full of depth.","x":"Er zijn dingen die we liever niet openen, en toch trekken ze ons aan. Dit werk speelt met die verleiding. Het laat een kier, net genoeg om te blijven kijken, en te blijven raden.","xe":"There are things we would rather not open, and still they draw us in. This work plays with that temptation. It leaves a gap, just enough to keep looking, and to keep wondering."},{"id":"019","nr":"NV-019","thema":"abstract","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#c70202","pal":["#ca0303","#dd0101","#980303","#de0000","#d90a0a"],"p":11,"t":"Verbijsterend Rood I","d":"Rood in tientallen tinten, opgebouwd uit rustige rechthoeken die elkaar net niet raken. Het eerste deel van haar rode reeks. Voor wie van één kleur houdt, maar die dan ten volle wil beleven.","own":true,"e":"Red in dozens of shades, built from calm rectangles that just fail to touch. The first part of her red series. For those who love one colour and want to experience it to the full.","x":"Wie één kleur werkelijk liefheeft, ziet er duizend in. Dit rood is geen achtergrond maar een wereld, gelaagd en levend. Het vraagt om een eigenaar die durft te kiezen.","xe":"Whoever truly loves one colour sees a thousand within it. This red is not a background but a world, layered and alive. It asks for an owner who dares to choose."},{"id":"020","nr":"NV-020","thema":"abstract","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#a60a0a","pal":["#e00102","#790507","#ba1213","#7e0103","#cc2f2a"],"p":11,"t":"Verbijsterend Rood II","d":"Het tweede deel van haar rode reeks. Hier opent het rood zich als een ruimte, doorsneden door één diagonale lijn die het vlak in beweging brengt. Samen met deel I vormt het een sprekend paar.","own":true,"e":"The second part of her red series. Here the red opens like a room, cut through by a single diagonal that sets the surface in motion. Together with part I it forms a striking pair.","x":"Eén lijn kan alles veranderen. Zoals één ontmoeting, één zin, één besluit. Hier snijdt een diagonaal door het rood, en het vlak komt tot leven. Samen met deel I vertelt het over wat er gebeurt als iets in beweging komt.","xe":"One line can change everything. Like one encounter, one sentence, one decision. Here a diagonal cuts through the red and the plane comes alive. Together with part I it speaks of what happens when something begins to move."},{"id":"021","nr":"NV-021","thema":"landschap","kleur":["paars","rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#6e406e","pal":["#6f3978","#361c4a","#6a2241","#8d649b","#c1aac4"],"p":12,"t":"Purperen Kloof","d":"Rotsformaties in violet en purper onder een zacht roze hemel. Het landschap is eerder gevoeld dan beschreven, een herinnering aan een plek in plaats van een afbeelding ervan. Rijk en dromerig van kleur.","own":false,"e":"Rock formations in violet and purple beneath a soft pink sky. The landscape is felt rather than described, the memory of a place rather than a picture of it. Rich and dreamlike in colour.","x":"Sommige plekken onthoud je niet zoals ze waren, maar zoals ze voelden. Dit is zo'n herinnering: dromerig, warm, een beetje onwerkelijk. Precies daarom zo waar.","xe":"Some places you remember not as they were, but as they felt. This is such a memory: dreamlike, warm, a little unreal. And precisely for that reason, so true."},{"id":"022","nr":"NV-022","thema":"abstract","kleur":["rood","zwart"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#7e6772","pal":["#171c30","#6d182d","#a28c94","#e8e2de","#bfd3d4"],"p":12,"t":"Aderen","d":"Bordeauxrode lijnen vertakken zich over ijsblauw en nachtblauw, als aderen of rivieren op een kaart. Grafisch en elegant, met een sterke tekening. Een werk dat goed samengaat met strak, modern meubilair.","own":false,"e":"Burgundy lines branch across ice blue and midnight blue, like veins or rivers on a map. Graphic and elegant, with a strong drawn line. A work that pairs well with clean, modern furniture.","x":"Alles wat leeft, is met iets verbonden. Rivieren met de zee, aderen met het hart, mensen met elkaar. Dit werk tekent die verbindingen, fijn en onmisbaar.","xe":"Everything that lives is connected to something. Rivers to the sea, veins to the heart, people to one another. This work draws those connections, fine and indispensable."},{"id":"023","nr":"NV-023","thema":"abstract","kleur":["oranje"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#7f573d","pal":["#22142e","#5e3a41","#ce8f29","#a56b3b","#d6b06e"],"p":13,"t":"Oker en Aubergine","d":"Goudgeel en oker lichten op tussen diep violet en aubergine, als avondlicht op een rotswand. Warm, rijk en vol contrast. Een kleurpalet dat bijzonder mooi is bij hout, leer en warme stoffen.","own":false,"e":"Golden yellow and ochre glow between deep violet and aubergine, like evening light on a rock face. Warm, rich and full of contrast. A palette that is especially beautiful alongside wood, leather and warm fabrics.","x":"Het licht aan het eind van de dag is het mooiste, omdat je weet dat het weggaat. Dit doek houdt dat gouden ogenblik vast, warm en een beetje weemoedig.","xe":"The light at the end of the day is the most beautiful, because you know it is leaving. This canvas holds that golden moment, warm and a little wistful."},{"id":"024","nr":"NV-024","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#515f79","pal":["#253c6f","#211a34","#496594","#a5a99a","#c6d5bb"],"p":13,"t":"Tesserae","d":"Honderden kleine vlakken in blauw, violet en mint vormen samen een levendig mozaïek. Van dichtbij abstract, van afstand bijna een landschap. Bij elke blik ontdek je iets nieuws.","own":false,"e":"Hundreds of small planes in blue, violet and mint come together in a lively mosaic. Abstract up close, almost a landscape from a distance. Every look reveals something new.","x":"Een leven bestaat uit duizenden kleine momenten die pas op afstand een beeld vormen. Zo werkt dit mozaïek ook: van dichtbij losse stukjes, van ver een geheel dat klopt.","xe":"A life is made of thousands of small moments that form an image only from a distance. This mosaic works the same way: up close, separate pieces; from afar, a whole that makes sense."},{"id":"025","nr":"NV-025","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#2d7b8e","pal":["#04a5aa","#1473a6","#112136","#40b2c5","#d6b79f"],"p":14,"t":"Branding","d":"Lagen turquoise en zalm schuiven als golven over elkaar, met een donkere strook als een rotsige kust. Fris en vol beweging, met de zilte helderheid van de zee.","own":false,"e":"Layers of turquoise and salmon slide over each other like waves, with a dark band like a rocky shore. Fresh and full of movement, with the salty clarity of the sea.","x":"De zee komt steeds terug, wat er ook gebeurt. Er zit troost in die herhaling. Dit werk brengt dat ritme in huis: golf na golf, adem na adem.","xe":"The sea always returns, whatever happens. There is comfort in that repetition. This work brings that rhythm home: wave after wave, breath after breath."},{"id":"026","nr":"NV-026","thema":"stad","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#6a775c","pal":["#2fa5a4","#426657","#831a15","#b2a53d","#b8ca8a"],"p":14,"t":"Middagstraat","d":"Een straat in zonovergoten turquoise, geflankeerd door rode gebouwen en een poort. De perspectieflijnen trekken je de diepte in. Je voelt de warmte van het zuiden en de stilte van het middaguur.","own":false,"e":"A street in sunlit turquoise, flanked by red buildings and a gateway. The lines of perspective pull you into the depth. You feel the warmth of the south and the stillness of midday.","x":"Op het heetste uur wordt het stil in het zuiden. Luiken dicht, schaduw op straat, de wereld even op pauze. Dit doek bewaart die stilte voor de drukke dagen hier.","xe":"At the hottest hour the south falls silent. Shutters closed, shade on the street, the world briefly on pause. This canvas keeps that stillness for the busy days here."},{"id":"027","nr":"NV-027","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#476681","pal":["#1b698b","#313d69","#0a456f","#cfc7d0","#b59073"],"p":15,"t":"Laatste Licht","d":"Een horizon in nachtblauw, met één strook oranje licht waar de zon net onder is. Alles is rust, het einde van de dag boven de kust. Een werk om bij stil te worden.","own":false,"e":"A horizon in midnight blue, with a single band of orange light where the sun has just set. Everything is calm: the end of the day above the coast. A work to fall quiet before.","x":"Het einde van iets kan het mooiste deel zijn. De zon is weg, het licht nog niet. In die laatste streep oranje zit alles wat de dag was, en alles wat morgen nog kan worden.","xe":"The end of something can be its most beautiful part. The sun has gone, the light not yet. In that last band of orange lies everything the day was, and everything tomorrow may still become."},{"id":"028","nr":"NV-028","thema":"abstract","kleur":["blauw","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#6e7d73","pal":["#4ba9b4","#2d2238","#d2a152","#d9caa8","#6c7566"],"p":15,"t":"Goudeiland","d":"Een goudgele vorm drijft in turquoise en violet, als een eiland dat oplicht in de schemering. Warm licht in koel water. Een werk met een sterk middelpunt en een rustige omgeving.","own":false,"e":"A golden form floats in turquoise and violet, like an island glowing at dusk. Warm light in cool water. A work with a strong centre and calm surroundings.","x":"Iedereen heeft een plek waar het licht nog brandt als de rest al schemert. Een mens, een herinnering, een thuis. Dit werk is die plek: goud in koel water, en een vaste koers in de avond.","xe":"Everyone has a place where the light still burns when everything else is dusk. A person, a memory, a home. This work is that place: gold in cool water, and a steady course through the evening."},{"id":"029","nr":"NV-029","thema":"abstract","kleur":["geel","blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#ada990","pal":["#aea16e","#455d66","#eae0cd","#d5cca8","#e9d2ba"],"p":16,"t":"Kaart van een Stad","d":"Op een lichte ondergrond ontvouwt zich een plattegrond van blokken, lijnen en blauw, als een stad gezien vanuit de lucht. Luchtig, precies en vol detail. Mooi in een werkkamer of studeerkamer.","own":false,"e":"On a pale ground a plan of blocks, lines and blue unfolds, like a city seen from the air. Airy, precise and full of detail. Lovely in a study or library.","x":"Van bovenaf zie je pas hoe alles samenhangt. Straten die naar elkaar toe lopen, levens die elkaar kruisen. Een werk voor wie graag overzicht heeft, en van de details blijft houden.","xe":"Only from above do you see how everything connects. Streets running towards each other, lives that cross. A work for those who like an overview, and still love the details."},{"id":"030","nr":"NV-030","thema":"abstract","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#ae7d4e","pal":["#af994a","#4c5d25","#d14e40","#f1c1a5","#e69f71"],"p":16,"t":"Rozentuin","d":"Roze en rode vlakjes bloeien op tegen groen en oker, als een tuin in de volle zomer. Het werk is los geschilderd, met de vrolijkheid van een ommuurde tuin. Fris en hartelijk.","own":false,"e":"Pink and red patches bloom against green and ochre, like a garden in high summer. Loosely painted, with the cheer of a walled garden. Fresh and warm-hearted.","x":"Een tuin is geduld dat bloeit. Wat je ooit plantte, komt terug wanneer je het niet meer verwacht. Dit werk heeft die blijde verrassing: zomer, ook op een grijze dag.","xe":"A garden is patience in bloom. What you once planted returns when you no longer expect it. This work has that glad surprise: summer, even on a grey day."},{"id":"031","nr":"NV-031","thema":"abstract","kleur":["blauw","geel"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#adc4b4","pal":["#e8d9d3","#9ec5c0","#bbd6d4","#6f9898","#f0de7b"],"p":17,"t":"Zuiden","d":"Lichtblauwe, gele en roze blokjes liggen als witte huizen in de zon aan de Middellandse Zee. Het werk heeft de helderheid van een zomerochtend in het zuiden. Licht en ontspannen.","own":false,"e":"Light blue, yellow and pink blocks lie like white houses in the Mediterranean sun. The work has the clarity of a summer morning in the south. Light and relaxed.","x":"Het is het gevoel van de eerste vakantieochtend: het raam open, het licht wit, de dag nog helemaal van jou. Dit werk brengt dat gevoel terug, elke keer dat u langsloopt.","xe":"It is the feeling of the first morning of a holiday: window open, light white, the whole day still yours. This work brings that feeling back every time you pass."},{"id":"032","nr":"NV-032","thema":"abstract","kleur":["rood","geel"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#bf9d81","pal":["#ad917a","#b45e59","#e3dbbc","#e4be7b","#babb96"],"p":17,"t":"Zachte Storm","d":"Roze, geel en blauw kruisen elkaar in snelle, zekere penseelstreken. Zacht van kleur, krachtig van gebaar: een storm in pastel. Een werk vol energie dat toch rust uitstraalt.","own":false,"e":"Pink, yellow and blue cross in rapid, assured brushstrokes. Soft in colour, strong in gesture: a storm in pastel. A work full of energy that still radiates calm.","x":"Zachtheid en kracht sluiten elkaar niet uit. Wie dat weet, herkent zichzelf in deze storm van pastel: bewogen, vastberaden, en toch nooit hard.","xe":"Gentleness and strength do not exclude one another. Whoever knows that will recognise themselves in this storm of pastel: moved, determined, and yet never harsh."},{"id":"033","nr":"NV-033","thema":"abstract","kleur":["blauw","oranje"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#858c86","pal":["#283d71","#807b63","#dfd8cd","#d4b58e","#8fb299"],"p":18,"t":"Fragments","d":"Landschappen zijn verdeeld, maar het blijft één aarde. Uit die overtuiging schilderde Nanny Fragments: vlakken van blauw, groen, oker en wit, elk met een eigen richting en een eigen verhaal, die samen toch één harmonieus geheel vormen. Eenheid in verscheidenheid. Een stil pleidooi om over grenzen heen te kijken, en elkaar te vinden.","own":true,"e":"Landscapes are divided, yet it remains one earth. From that conviction Nanny painted Fragments: planes of blue, green, ochre and white, each with its own direction and its own story, which together still form one harmonious whole. Unity in diversity. A quiet plea to look beyond borders, and to find one another.","x":"Wie veel heeft gereisd, weet dat mensen overal hetzelfde verlangen. Een thuis, een horizon, een ander om mee te delen. Fragments is gemaakt van die wetenschap: alles wat verschilt, past toch in één beeld.","xe":"Whoever has travelled widely knows that people everywhere long for the same things. A home, a horizon, someone to share it with. Fragments is made of that knowledge: everything that differs still fits into one image."},{"id":"034","nr":"NV-034","thema":"landschap","kleur":["blauw","groen"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#588355","pal":["#143132","#2f725d","#56a472","#b1b660","#ddd64a"],"p":18,"t":"Veenland","d":"Een donker silhouet van bomen staat in een gloed van geel en groen, ruig en natuurlijk. Het landschap is los en waterig geschilderd. Een stuk Nederlandse natuur, vrij geïnterpreteerd.","own":false,"e":"A dark silhouette of trees stands in a glow of yellow and green, wild and natural. The landscape is painted loosely and fluidly. A piece of Dutch nature, freely interpreted.","x":"Er is iets in het Nederlandse landschap dat je pas mist als je het niet meer ziet. Laag, nat, eindeloos. Dit werk is een groet aan dat land, ruig en vertrouwd.","xe":"There is something in the Dutch landscape you only miss once you no longer see it. Low, wet, endless. This work is a greeting to that land, rugged and familiar."},{"id":"035","nr":"NV-035","thema":"landschap","kleur":["geel","blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#c3ccbd","pal":["#ccdcdc","#e4e0d5","#97a89e","#c2cfbb","#eadaa4"],"p":19,"t":"Stilte aan Zee","d":"Zand, zee en één gouden streep licht, in zachte, transparante tinten. Het is een van haar meest ingetogen werken. Rust in zijn puurste vorm, rechtsonder gesigneerd.","own":false,"e":"Sand, sea and a single golden line of light, in soft, translucent tones. It is one of her most restrained works. Calm in its purest form, signed lower right.","x":"Soms is weinig alles. Zand, water, één streep licht. Wie dit werk in huis haalt, haalt de stilte van een vroege ochtend aan zee binnen, en de ruimte om even niets te hoeven.","xe":"Sometimes little is everything. Sand, water, one line of light. Whoever brings this work home brings in the stillness of an early morning by the sea, and the space to need nothing for a while."},{"id":"036","nr":"NV-036","thema":"landschap","kleur":["zwart","geel"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#878f85","pal":["#394140","#747b6a","#9dada0","#dde0db","#c8c4b5"],"p":19,"t":"Polderweg","d":"Een weg loopt uit in een wijd landschap onder een bewolkte hemel, zoals alleen Nederland die kent. Het licht is grijs en zilver, de ruimte eindeloos. Een werk dat een kamer groter maakt.","own":false,"e":"A road runs out into a wide landscape under a clouded sky, as only the Netherlands knows it. The light is grey and silver, the space endless. A work that makes a room feel larger.","x":"Een weg die in de verte verdwijnt, is altijd een belofte. Je weet niet wat er komt, alleen dat het ruim is. Dit werk geeft een kamer die adem, en zijn bewoner die blik vooruit.","xe":"A road disappearing into the distance is always a promise. You do not know what lies ahead, only that it is wide. This work gives a room that breath, and its owner that forward gaze."},{"id":"037","nr":"NV-037","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#69a8b7","pal":["#0d66a3","#349bb6","#81c0c7","#e6e4cf","#d1d4aa"],"p":20,"t":"Glinstering","d":"Blauw, wit en geel flonkeren als zonlicht op water. Het werk is opgebouwd uit korte, levendige toetsen. Licht en opgewekt, met de frisheid van een dag aan het water.","own":false,"e":"Blue, white and yellow sparkle like sunlight on water. The work is built from short, lively touches. Light and cheerful, with the freshness of a day by the water.","x":"Gelukkige momenten zijn vaak klein: licht op water, een glinstering die je even doet glimlachen. Dit doek verzamelt er honderden. Een werk dat goed humeur verspreidt zonder het te eisen.","xe":"Happy moments are often small: light on water, a glint that makes you smile for a second. This canvas gathers hundreds of them. A work that spreads good humour without demanding it."},{"id":"038","nr":"NV-038","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#658987","pal":["#3c7278","#214a5f","#ccd6d0","#6ba6ab","#cbb167"],"p":20,"t":"Diepte","d":"Diep blauw met strepen oker en zwart, alsof het licht tot op de bodem van de zee reikt. Gelaagd en rijk aan textuur. Een werk om lang naar te kijken.","own":false,"e":"Deep blue with streaks of ochre and black, as if light reached the seabed. Layered and rich in texture. A work to look at for a long time.","x":"Onder elk oppervlak ligt meer dan je ziet. Bij water, bij mensen, bij jezelf. Dit werk nodigt uit om dieper te kijken, en beloont wie dat doet.","xe":"Beneath every surface lies more than you can see. In water, in people, in yourself. This work invites you to look deeper, and rewards those who do."},{"id":"039","nr":"NV-039","thema":"abstract","kleur":["blauw","geel"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#69a38e","pal":["#8fc9a1","#018bc2","#e8e557","#0b4e8e","#3c97a6"],"p":21,"t":"Zeewind","d":"Diagonale stroken geel, blauw en wit, alsof de wind over het water jaagt. Je voelt de frisse lucht en de beweging. Een werk dat energie geeft zonder onrustig te worden.","own":false,"e":"Diagonal strips of yellow, blue and white, as if the wind were racing across the water. You feel the fresh air and the movement. A work that energises without becoming restless.","x":"Wind maakt je hoofd leeg. Op een dijk, op het strand, aan de reling van een boot. Dit werk heeft die frisheid: het waait door een kamer en neemt de zwaarte mee.","xe":"Wind clears your head. On a dyke, on the beach, at the rail of a boat. This work has that freshness: it blows through a room and carries the heaviness away."},{"id":"040","nr":"NV-040","thema":"landschap","kleur":["blauw","geel"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#80a396","pal":["#599c9a","#9ec5bf","#2a5456","#e6e2c3","#d6cd8f"],"p":21,"t":"Eb","d":"Teal, geel en grijs in losse, waterige vlekken. Een kust bij eb, stil en open, waar het water zich even heeft teruggetrokken. Zacht en bespiegelend.","own":false,"e":"Teal, yellow and grey in loose, watery patches. A coast at low tide, quiet and open, where the water has briefly withdrawn. Soft and contemplative.","x":"Bij eb wordt zichtbaar wat anders verborgen blijft. Het water trekt zich terug en laat ruimte. Er zit wijsheid in dat ritme: loslaten om opnieuw te kunnen ontvangen.","xe":"At low tide, what is usually hidden becomes visible. The water withdraws and leaves space. There is wisdom in that rhythm: letting go in order to receive again."},{"id":"041","nr":"NV-041","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#052c7f","pal":["#021e7a","#0346a8","#02073a","#033598","#1c61b2"],"p":22,"t":"Nocturne in Blauw","d":"Rechthoeken in alle tinten blauw rond een donkere opening, als ramen in de nacht. Het werk brengt rust en concentratie. Bijzonder mooi in een slaapkamer of werkkamer.","own":false,"e":"Rectangles in every shade of blue around a dark opening, like windows at night. The work brings calm and focus. Especially beautiful in a bedroom or study.","x":"'s Nachts, als het huis slaapt, worden gedachten helderder. Dit werk heeft de stilte van dat uur: blauw, geconcentreerd, met ergens een raam dat nog openstaat.","xe":"At night, when the house is asleep, thoughts grow clearer. This work has the stillness of that hour: blue, concentrated, with somewhere a window still open."},{"id":"042","nr":"NV-042","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#22226c","pal":["#021186","#0e156c","#0b2582","#98070a","#1a457c"],"p":22,"t":"Eiland","d":"Een rode vorm drijft in kobaltblauw, omringd door groen en geel. Eenvoudig van opbouw, krachtig van uitwerking. Het rood trekt de blik als een vuurtoren op zee.","own":false,"e":"A red form floats in cobalt blue, surrounded by green and yellow. Simple in structure, powerful in effect. The red draws the eye like a lighthouse at sea.","x":"Eén rode vorm in een zee van blauw: zo voelt het om iets of iemand te vinden die eruit springt. Een baken, een anker. Een werk over wat je richting geeft.","xe":"One red form in a sea of blue: that is how it feels to find something, or someone, who stands out. A beacon, an anchor. A work about what gives you direction."},{"id":"043","nr":"NV-043","thema":"abstract","kleur":["oranje"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#836761","pal":["#c9a984","#a17b63","#2a2b53","#5c4a4e","#945048"],"p":23,"t":"Partituur","d":"Druppels en lijnen in alle kleuren over een lichte grond, met een ritme dat aan muziek doet denken. Vrij en spontaan geschilderd. Een werk dat leven brengt in een rustig interieur.","own":false,"e":"Drips and lines in every colour across a pale ground, with a rhythm that recalls music. Painted freely and spontaneously. A work that brings life to a calm interior.","x":"Muziek kun je niet zien, maar hier komt het dichtbij. Een ritme dat ontstaat terwijl je kijkt, vrij en speels. Het werk maakt een stille kamer muzikaal.","xe":"You cannot see music, but here it comes close. A rhythm that emerges as you look, free and playful. The work makes a quiet room musical."},{"id":"044","nr":"NV-044","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#374b63","pal":["#4b2b35","#22718d","#112f68","#2e5573","#81856e"],"p":23,"t":"Firmament","d":"Spatten wit, geel en rood op diep blauw, als een hemel vol sterren. Het werk is vrij en gestisch geschilderd, met veel diepte. Een nachtelijk werk vol licht.","own":false,"e":"Splashes of white, yellow and red on deep blue, like a sky full of stars. Painted freely and gesturally, with great depth. A nocturnal work full of light.","x":"Wie in een heldere nacht omhoogkijkt, voelt zich klein en tegelijk verbonden met alles. Dit werk brengt die nacht naar binnen: diep, wijd, vol licht dat van ver komt.","xe":"Whoever looks up on a clear night feels small and at the same time connected to everything. This work brings that night indoors: deep, wide, full of light that has travelled far."},{"id":"045","nr":"NV-045","thema":"abstract","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#ac4633","pal":["#d4180b","#ed6220","#6d736f","#f08849","#801a1f"],"p":24,"t":"Rivierbedding","d":"Oranje en perzik stromen tussen rood en turquoise, als een rivier door een warm landschap. Levendig en vol beweging. Een werk dat een ruimte direct warmte geeft.","own":false,"e":"Orange and peach flow between red and turquoise, like a river through a warm landscape. Lively and full of movement. A work that brings instant warmth to a room.","x":"Water zoekt altijd zijn weg, hoe het land ook ligt. Er zit veerkracht in een rivier. Dit doek stroomt warm door een kamer, en herinnert eraan dat beweging ook doorzetten is.","xe":"Water always finds its way, however the land lies. There is resilience in a river. This canvas flows warmly through a room, and reminds you that movement is also perseverance."},{"id":"046","nr":"NV-046","thema":"abstract","kleur":["oranje","rood"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#bd4e2b","pal":["#de2e0a","#de5c2a","#4a1f1c","#e87a48","#efa36e"],"p":24,"t":"Terracotta","d":"Oranje en zalm met zwarte accenten, als zandsteen in het avondlicht. De verf is ruw en levendig opgezet. Aards en warm, een werk dat goed samengaat met natuurlijke materialen.","own":false,"e":"Orange and salmon with black accents, like sandstone in evening light. The paint is applied roughly and vividly. Earthy and warm, a work that pairs well with natural materials.","x":"Aarde, klei, zandsteen: materialen die ouder zijn dan wij en ons overleven. Nanny begon als keramiste; misschien zit die liefde voor het aardse hier nog in. Een werk dat gronding geeft.","xe":"Earth, clay, sandstone: materials older than we are, which will outlast us. Nanny began as a ceramicist; perhaps that love of the earthly still lives here. A work that grounds you."},{"id":"047","nr":"NV-047","thema":"abstract","kleur":["oranje"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#af755d","pal":["#472c4d","#bb4b2a","#d18e5b","#eac098","#eee0af"],"p":25,"t":"Oktober","d":"Oranje, violet en geel, doorkruist met zwarte lijnen als takken tegen een herfstlucht. Vurig en grillig. Een werk met de kleuren en de onrust van het najaar.","own":false,"e":"Orange, violet and yellow, crossed by black lines like branches against an autumn sky. Fiery and capricious. A work with the colours and restlessness of autumn.","x":"De herfst laat zien dat loslaten mooi kan zijn. Alles kleurt op voordat het valt. Dit werk heeft die vurige weemoed, en de belofte dat het daarna weer lente wordt.","xe":"Autumn shows that letting go can be beautiful. Everything blazes with colour before it falls. This work has that fiery wistfulness, and the promise that spring will come again."},{"id":"048","nr":"NV-048","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#7a4550","pal":["#e31603","#666185","#09173b","#c38873","#85181c"],"p":25,"t":"Kristal","d":"Hoekige rode en oranje vormen tegen blauw en zwart, helder en grafisch. De compositie heeft de precisie van een geslepen steen. Krachtig in een moderne ruimte.","own":false,"e":"Angular red and orange forms against blue and black, clear and graphic. The composition has the precision of a cut stone. Powerful in a modern space.","x":"Een kristal ontstaat onder druk en wordt er helder van. Er zit iets troostends in die gedachte. Dit werk is scherp, precies en stralend, als iets dat sterker uit iets moeilijks is gekomen.","xe":"A crystal forms under pressure and becomes clear because of it. There is something consoling in that thought. This work is sharp, precise and radiant, like something that emerged stronger from something hard."},{"id":"049","nr":"NV-049","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#969493","pal":["#7ab3ad","#dcb589","#735093","#88899f","#e7d357"],"p":26,"t":"Veer","d":"Geel, roze en blauw in zachte, veervormige streken. Licht als een zomerochtend, met een kleurenspel dat aan een regenboog doet denken. Een werk dat opvrolijkt zonder te schreeuwen.","own":false,"e":"Yellow, pink and blue in soft, feather-like strokes. As light as a summer morning, with an interplay of colour that recalls a rainbow. A work that uplifts without shouting.","x":"Lichtheid is een kunst. Niet zwaar maken wat licht mag zijn. Dit doek beheerst die kunst: het zweeft, het kleurt, het laat de lucht binnen.","xe":"Lightness is an art. Not making heavy what may stay light. This canvas masters that art: it floats, it colours, it lets the air in."},{"id":"050","nr":"NV-050","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#585762","pal":["#366686","#0c2b55","#9c254c","#c9b63c","#389889"],"p":26,"t":"Ontlading","d":"Felroze, geel en blauw spatten uiteen tegen donkerblauw, als vuurwerk boven de stad. Uitbundig en vol energie. Een werk voor wie van uitgesproken kleur houdt.","own":false,"e":"Bright pink, yellow and blue burst apart against dark blue, like fireworks above a city. Exuberant and full of energy. A work for those who love bold colour.","x":"Er zijn avonden die je je je hele leven herinnert. Een feest, een overwinning, een nacht vol vuurwerk. Dit werk viert zulke momenten, en nodigt uit om er nieuwe te maken.","xe":"There are evenings you remember for the rest of your life. A celebration, a victory, a night full of fireworks. This work celebrates such moments, and invites you to make new ones."},{"id":"051","nr":"NV-051","thema":"abstract","kleur":["geel","rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#ab9375","pal":["#b2aea1","#edc457","#157f69","#bc8287","#a65967"],"p":27,"t":"Voorjaar","d":"Roze, geel en groen openen zich als bloemen in de lente. Fris en hoopvol, met een losse, zekere toets. Een werk dat licht brengt in een ruimte.","own":false,"e":"Pink, yellow and green open like flowers in spring. Fresh and hopeful, with a loose, assured touch. A work that brings light into a room.","x":"Elk voorjaar is een klein wonder dat we gewoon vinden. Dit werk vindt het niet gewoon: het opent zich met dezelfde verwondering als de eerste bloesem na een lange winter.","xe":"Every spring is a small miracle we take for granted. This work does not take it for granted: it opens with the same wonder as the first blossom after a long winter."},{"id":"052","nr":"NV-052","thema":"abstract","kleur":["geel"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#837e41","pal":["#065173","#e6d415","#91371c","#eab12b","#8bae5b"],"p":27,"t":"Bloeiend Veld","d":"Geel en rood boven diep groen, als een veld vol bloemen in de zon. Het werk is warm en zomers van sfeer. Mooi in een eetkamer of keuken.","own":false,"e":"Yellow and red above deep green, like a field of flowers in the sun. Warm and summery in mood. Lovely in a dining room or kitchen.","x":"Het is het veld waar je als kind doorheen rende, met de zon in je nek. Dit werk ruikt bijna naar zomer. Een plek om naar terug te keren, zonder te hoeven reizen.","xe":"It is the field you ran through as a child, the sun on the back of your neck. This work almost smells of summer. A place to return to, without having to travel."},{"id":"053","nr":"NV-053","thema":"abstract","kleur":["rood","geel"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#a28b6a","pal":["#537681","#9a1d21","#eedf91","#edcc5a","#abc092"],"p":28,"t":"Improvisatie","d":"Rood, blauw en geel in spatten en blokken op wit, als een stuk muziek dat ter plekke ontstaat. Spontaan en vrij. Een werk vol levenslust.","own":false,"e":"Red, blue and yellow in splashes and blocks on white, like a piece of music composed on the spot. Spontaneous and free. A work full of zest for life.","x":"Het mooiste ontstaat soms zonder plan. Een gesprek dat een andere kant op gaat, een dag die verrassend loopt. Dit doek viert die spontaniteit, met de levenslust van iemand die durfde te spelen.","xe":"Sometimes the most beautiful things happen without a plan. A conversation that takes another turn, a day that surprises you. This canvas celebrates that spontaneity, with the zest of someone who dared to play."},{"id":"054","nr":"NV-054","thema":"abstract","kleur":["zwart"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#564735","pal":["#01033f","#e0b55a","#675e2f","#53141a","#5b993e"],"p":28,"t":"Vitrail","d":"Zwarte contouren omsluiten blauw, groen en oranje als een raam van glas-in-lood. Grafisch en kleurrijk, met een sterke tekening. Onderaan gesigneerd.","own":false,"e":"Black outlines enclose blue, green and orange like a stained-glass window. Graphic and colourful, with a strong drawn line. Signed at the bottom.","x":"In een kerk of oud huis valt het licht door gekleurd glas, en even wordt de ruimte heilig. Dit werk heeft iets van dat gevoel: kleur die licht vangt en een plek bijzonder maakt.","xe":"In a church or an old house, light falls through coloured glass, and for a moment the space becomes sacred. This work holds something of that feeling: colour that catches light and makes a place special."},{"id":"055","nr":"NV-055","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#6f7169","pal":["#083676","#89343b","#628d89","#f0d64d","#9fc289"],"p":29,"t":"Carrousel","d":"Rood, blauw en geel in een drukke, feestelijke compositie die ronddraait als een draaimolen. Je hoort de muziek bijna. Een werk voor een levendige ruimte.","own":false,"e":"Red, blue and yellow in a busy, festive composition that turns like a merry-go-round. You can almost hear the music. A work for a lively room.","x":"Een draaimolen is jeugd, kermis, het geluid van een orgel in de verte. Dit werk draait met dezelfde vrolijkheid. Wie ernaar kijkt, wordt even jonger.","xe":"A carousel is childhood, the fair, the sound of an organ in the distance. This work turns with the same joy. Whoever looks at it grows young again for a while."},{"id":"056","nr":"NV-056","thema":"abstract","kleur":["geel","blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#6d6944","pal":["#041d77","#4a844b","#f7e206","#7d293f","#ddcf21"],"p":29,"t":"Labyrint","d":"Felgeel met zwarte, rode en blauwe contouren die als een doolhof door elkaar lopen. Speels en uitgesproken. Een werk dat het oog blijft uitdagen.","own":false,"e":"Bright yellow with black, red and blue outlines winding through each other like a maze. Playful and outspoken. A work that keeps challenging the eye.","x":"Het leven loopt zelden rechtdoor. Er zijn bochten, doodlopende paden en onverwachte uitwegen. Dit doek maakt er een spel van, en laat zien dat zoeken ook plezier kan zijn.","xe":"Life rarely runs in a straight line. There are bends, dead ends and unexpected ways out. This canvas makes a game of it, and shows that searching can also be a joy."},{"id":"057","nr":"NV-057","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":1.0,"avg":"#9a5459","pal":["#3d0e10","#940c16","#eabec5","#aa6a6d","#ebd9de"],"p":30,"t":"De Tram","d":"Een groot doek in rood, roze en wit rond een diepe, donkere kern. Op de foto van haar atelier staat juist dit werk op de ezel, met Nanny ervoor, penseel in de hand. Een werk met een bijzondere plaats in haar oeuvre.","own":true,"e":"A large canvas in red, pink and white around a deep, dark core. In the photograph of her studio it is this very work on the easel, with Nanny before it, brush in hand. A work with a special place in her oeuvre.","x":"Op de foto van Nanny in haar atelier staat dit doek op de ezel. Het is dus niet zomaar een werk, maar een moment uit haar leven, bevroren in rood. Wie het bezit, bewaart een stuk van haar dagen.","xe":"In the photograph of Nanny in her studio, this canvas stands on the easel. It is therefore not just a work, but a moment from her life, frozen in red. Whoever owns it keeps a piece of her days."},{"id":"058","nr":"NV-058","thema":"abstract","kleur":["blauw","zwart"],"ori":"vierkant","type":"enkel","ar":1.0025,"avg":"#3c5073","pal":["#0c0c14","#9eb2d0","#365d93","#07266a","#1e263f"],"p":31,"t":"Neonlicht","d":"Verticale banen blauw en zwart, doorsneden met wit licht, als neon in een nachtelijke stad. Stoer en atmosferisch. Een van haar sterkste werken in blauw.","own":true,"e":"Vertical bands of blue and black, cut through with white light, like neon in a city at night. Bold and atmospheric. One of her strongest works in blue.","x":"Een stad bij nacht heeft een eigen eenzaamheid, en een eigen schoonheid. Neonlicht dat brandt voor wie nog onderweg is. Dit werk kent beide, en maakt er iets stoers en tedere tegelijk van.","xe":"A city at night has its own loneliness, and its own beauty. Neon burning for those still on their way. This work knows both, and makes of them something bold and tender at once."},{"id":"059","nr":"NV-059","thema":"abstract","kleur":["zwart","blauw"],"ori":"vierkant","type":"enkel","ar":1.0045,"avg":"#1b314a","pal":["#242e43","#070c15","#3881b3","#16131a","#020619"],"p":32,"t":"The Canyon","d":"Lichtblauw breekt door diep zwart en violet, als licht dat in een kloof valt. Het werk is dramatisch en tegelijk stil. Een krachtig doek in vierkant formaat.","own":true,"e":"Light blue breaks through deep black and violet, like light falling into a gorge. Dramatic and quiet at the same time. A powerful canvas in square format.","x":"Licht reikt verder dan je denkt, zelfs tot op de bodem van een kloof. Dit werk gaat over die belofte: hoe diep het ook is, er valt ergens licht naar binnen.","xe":"Light reaches further than you think, even to the floor of a canyon. This work is about that promise: however deep it goes, somewhere the light falls in."},{"id":"060","nr":"NV-060","thema":"abstract","kleur":["blauw","zwart"],"ori":"vierkant","type":"enkel","ar":1.0045,"avg":"#174662","pal":["#2ea5d3","#000205","#235581","#031732","#101724"],"p":33,"t":"Part of the River","d":"Een lichtblauwe stroom met een roze kern, omringd door zwart. Intiem en krachtig, als een glimp van water tussen donkere oevers. Een werk met veel diepte.","own":true,"e":"A light blue stream with a pink core, surrounded by black. Intimate and powerful, like a glimpse of water between dark banks. A work of great depth.","x":"Je stapt nooit twee keer in dezelfde rivier, en toch blijft het dezelfde rivier. Nanny noemde dit werk Part of the River: misschien over hoe ieder van ons maar een deel van de stroom is, en daarin toch onmisbaar.","xe":"You never step into the same river twice, and yet it remains the same river. Nanny named this work Part of the River: perhaps about how each of us is only part of the current, and yet indispensable within it."},{"id":"061","nr":"NV-061","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"drieluik","ar":1.2681,"avg":"#c19170","pal":["#dbded4","#fbc363","#a01926","#8e7962","#fbe16e"],"p":34,"t":"Iris en Bloesem","d":"Een drieluik in rood, oranje, geel en roze op wit, met accenten van diep blauw. Over drie staande panelen opent zich één grote bloei: van de koele, blauwe lucht links naar het opgerichte geel van de iris rechts. Licht en stralend, gemaakt voor een brede wand.","own":false,"e":"A triptych in red, orange, yellow and pink on white, with accents of deep blue. Across three upright panels a single great blossoming unfolds: from the cool blue sky on the left to the upright yellow of the iris on the right. Light and radiant, made for a wide wall.","x":"Drie panelen, één beweging. Wat links begint als een vlaag van blauw, opent zich in het midden en richt zich rechts op als een iris in de zon. Een werk over groei en overgave, en over hoe iets pas helemaal zichzelf wordt wanneer het de ruimte krijgt.","xe":"Three panels, one movement. What begins on the left as a gust of blue opens in the middle and rises on the right like an iris in the sun. A work about growth and surrender, and about how something only becomes entirely itself when it is given room.","gaps":[[32.331,35.042],[66.683,69.394]]},{"id":"063","nr":"NV-063","thema":"abstract","kleur":["rood"],"ori":"staand","type":"enkel","ar":0.6991,"avg":"#c46872","pal":["#e8d2ce","#cd8d9b","#dc0708","#812443","#de3638"],"p":35,"t":"Cartografie","d":"Rood druipt over wit, doorkruist door donkere lijnen als op een oude kaart. Toeval en tekening gaan hier samen. Een werk met een eigenzinnige, gelaagde schoonheid.","own":false,"e":"Red drips over white, crossed by dark lines as on an old map. Chance and drawing come together here. A work of idiosyncratic, layered beauty.","x":"Niet elke weg staat op de kaart; sommige ontstaan pas als je ze loopt. Hier druipt de verf zijn eigen route, en de lijnen volgen. Een werk over het toeval dat een leven richting geeft.","xe":"Not every road is on the map; some only appear as you walk them. Here the paint drips its own route, and the lines follow. A work about the chance that gives a life its direction."},{"id":"064","nr":"NV-064","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#912c2f","pal":["#720102","#d50101","#7e7278","#99abb4","#751b21"],"p":36,"t":"Massief","d":"Een tweeluik met machtige rode massa's onder een grijze lucht, als een bergketen in het laatste licht. Dramatisch en groots. Een statement op een brede wand.","own":false,"e":"A diptych of mighty red masses beneath a grey sky, like a mountain range in the last light. Dramatic and grand. A statement on a wide wall.","x":"Bergen staan er al eeuwen, en zullen er nog eeuwen staan. Wie voor dit tweeluik staat, voelt die onverzettelijkheid. Iets om op te leunen als de dagen onzeker zijn.","xe":"Mountains have stood for centuries, and will stand for centuries more. Whoever stands before this diptych feels that steadfastness. Something to lean on when the days are uncertain.","gaps":[[48.047,52.139]]},{"id":"065","nr":"NV-065","thema":"stad","kleur":["zwart","blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0398,"avg":"#3c3f43","pal":["#203b43","#251617","#121518","#7e9a9e","#581110"],"p":37,"t":"Dirty Street","d":"Een tweeluik met donkere gevels in petrol en rood, rauw en stedelijk. De titel schilderde Nanny zelf linksonder op het doek. Een werk met de sfeer van een grote stad na zonsondergang.","own":true,"e":"A diptych of dark façades in petrol and red, raw and urban. Nanny painted the title onto the canvas herself, lower left. A work with the atmosphere of a big city after sunset.","x":"Het is de stad na donker: rauw, echt, onopgesmukt, zoals je haar alleen kent als je er lang genoeg rondloopt. Er zit schoonheid in wat niet gepolijst is, en eerlijkheid in wat niet mooier wordt voorgesteld dan het is.","xe":"It is the city after dark: raw, real, unadorned, the way you only know it after walking its streets long enough. There is beauty in what has not been polished, and honesty in what is not made prettier than it is.","gaps":[[47.931,52.069]]},{"id":"066","nr":"NV-066","thema":"abstract","kleur":["rood","blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#816672","pal":["#0e2d4c","#dac4c0","#94808e","#c01e27","#503038"],"p":38,"t":"Ritme van de Stad","d":"Een tweeluik in wit, roze, rood en nachtblauw. Fragmenten van een stad die nooit stilstaat, verdeeld over twee panelen die elkaar aanvullen. Energiek en verfijnd.","own":false,"e":"A diptych in white, pink, red and midnight blue. Fragments of a city that never stands still, divided over two panels that complete each other. Energetic and refined.","x":"Een stad slaapt nooit helemaal, en dat is haar charme. Altijd ergens licht, altijd iemand onderweg. Dit tweeluik vangt dat ritme, verfijnd en onvermoeibaar.","xe":"A city never quite sleeps, and that is its charm. Always a light somewhere, always someone on the move. This diptych captures that rhythm, refined and tireless.","gaps":[[48.047,52.139]]},{"id":"067","nr":"NV-067","thema":"abstract","kleur":["groen","rood"],"ori":"vierkant","type":"tweeluik","ar":1.0398,"avg":"#58714b","pal":["#0caf66","#7b100f","#594937","#82d27f","#7daa85"],"p":39,"t":"Twee Seizoenen","d":"Een tweeluik van twee werelden: links gloeiend rood rond een witte kern, rechts een paneel dat bekendstaat als The End of an Era. Geïnspireerd door de val van de Berlijnse Muur in 1989, maar minder over politiek dan over de innerlijke verschuiving wanneer een zware last wegvalt. Nanny noemde het 'het gevoel erna': de stilte en de hoop die volgen. Helend groen, blauw en zacht goud, met een gloeiende rode sintel als teken van kracht die blijft.","own":false,"e":"A diptych of two worlds: glowing red around a white core on the left, and on the right a panel known as The End of an Era. Inspired by the fall of the Berlin Wall in 1989, yet less about politics than about the inner shift when a heavy burden lifts. Nanny called it 'the feeling after': the silence and the hope that follow. Healing greens, blues and soft gold, with a glowing red ember as a sign of strength that endures.","x":"Iedereen kent een muur die ooit viel: een angst, een last, een oude grens. Wat daarna komt is stil en een beetje onwennig, en vol hoop. Dit werk geeft dat gevoel een plek aan de muur.","xe":"Everyone knows a wall that once fell: a fear, a burden, an old boundary. What comes after is quiet and a little unfamiliar, and full of hope. This work gives that feeling a place on the wall.","gaps":[[47.931,52.069]]},{"id":"068","nr":"NV-068","thema":"landschap","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.9369,"avg":"#b92f29","pal":["#dc0804","#b20403","#8c6364","#c63823","#9d898c"],"p":40,"t":"Branding in Rood","d":"Een gelaagde rode vlakte met een witte branding onder een grijze lucht. Het landschap is teruggebracht tot kleur en horizon. Weids en warm.","own":false,"e":"A layered red plain with white surf beneath a grey sky. The landscape is reduced to colour and horizon. Wide and warm.","x":"Waar land en zee elkaar raken, is altijd beweging. Ook hier: een rode vlakte die breekt in wit. Een werk over de grens tussen wat vast is en wat stroomt.","xe":"Where land and sea meet, there is always movement. Here too: a red plain breaking into white. A work about the border between what is solid and what flows."},{"id":"069","nr":"NV-069","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":1.0324,"avg":"#ab3a3d","pal":["#db0101","#910203","#e1bba6","#813849","#a09ca4"],"p":40,"t":"Vleugelslag","d":"Rood, wit en blauw bewegen over het doek als vleugels in volle vlucht. Een groot, zelfverzekerd gebaar vol energie. Een van de krachtigste werken in de collectie.","own":false,"e":"Red, white and blue move across the canvas like wings in full flight. A large, confident gesture full of energy. One of the most powerful works in the collection.","x":"Opvliegen vraagt maar één beslissing: je vleugels spreiden. Dit doek is die beslissing, groot en zonder aarzeling. Een werk voor wie durft, of wil leren durven.","xe":"Taking flight requires only one decision: spreading your wings. This canvas is that decision, large and without hesitation. A work for those who dare, or who want to learn to dare."},{"id":"070","nr":"NV-070","thema":"abstract","kleur":["rood","blauw"],"ori":"vierkant","type":"enkel","ar":1.036,"avg":"#69112c","pal":["#ce0303","#051e6f","#8c070b","#46243e","#5b111e"],"p":40,"t":"Botsing","d":"Rood en kobaltblauw botsen in vrije, krachtige streken, als twee elementen die elkaar ontmoeten. Rechtsonder gesigneerd. Een werk voor wie van uitgesproken contrast houdt.","own":false,"e":"Red and cobalt collide in free, powerful strokes, like two elements meeting. Signed lower right. A work for lovers of strong contrast.","x":"Uit tegenstellingen ontstaat iets nieuws. Vuur en water, rood en blauw, twee mensen die het niet eens zijn. Dit werk laat zien dat een botsing ook een begin kan zijn.","xe":"From opposites, something new is born. Fire and water, red and blue, two people who disagree. This work shows that a collision can also be a beginning."},{"id":"071","nr":"NV-071","thema":"landschap","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":0.9863,"avg":"#9b0f06","pal":["#9e0101","#8a0101","#960001","#b9411c","#8e0302"],"p":41,"t":"Death Valley","d":"Haar laatste werk, en een van haar meest persoonlijke. Diep rood, goudoker en een aardend zwart: de weidse stilte van Death Valley National Park, in de Verenigde Staten. Meer dan een landschap is het een overpeinzing over leven, sterfelijkheid en wat er aan het eind werkelijk overblijft. Nanny's afscheid, en een plek voor bezinning en herinnering.","own":true,"e":"Her final work, and one of her most personal. Deep red, golden ochre and a grounding black: the vast stillness of Death Valley National Park, in the United States. More than a landscape, it is a meditation on life, mortality and what truly remains at the end. Nanny's farewell, and a place for reflection and remembrance.","x":"Het is ontroerend om te bedenken dat dit het laatste doek is waar haar penseel overheen ging. Een woestijn, zonder haast, zonder mensen, met licht aan de horizon. Wie dit werk bezit, bewaart haar laatste woord.","xe":"It is moving to think that this is the last canvas her brush passed over. A desert, without hurry, without people, with light on the horizon. Whoever owns this work keeps her final word."},{"id":"072","nr":"NV-072","thema":"landschap","kleur":["zwart"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#1b1820","pal":["#101119","#0d0807","#0b0706","#473f55","#080608"],"p":42,"t":"Nachtwolk","d":"Bijna geheel zwart, met één roze wolk en een streep blauw. Een stil, mysterieus werk dat zich langzaam openbaart. Rechtsonder gesigneerd.","own":false,"e":"Almost entirely black, with a single pink cloud and a line of blue. A quiet, mysterious work that reveals itself slowly. Signed lower right.","x":"Niet alles hoeft zich meteen te laten zien. Dit werk opent zich langzaam, zoals een nacht waarin je ogen wennen aan het donker. Wie geduld heeft, ziet de roze wolk oplichten.","xe":"Not everything needs to reveal itself at once. This work opens slowly, like a night in which your eyes adjust to the dark. Whoever is patient sees the pink cloud begin to glow."},{"id":"073","nr":"NV-073","thema":"abstract","kleur":["zwart","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#765741","pal":["#dcc9a6","#2a0e07","#a3724d","#1b0905","#4d1f14"],"p":42,"t":"Woud bij Nacht","d":"Banen wit en geel op diep bruin, als licht dat door een donker bos valt. Sfeervol en ingetogen. Een werk met de stilte van een nachtwandeling.","own":false,"e":"Bands of white and yellow on deep brown, like light falling through a dark forest. Atmospheric and restrained. A work with the stillness of a walk at night.","x":"In een donker bos lijkt elk lichtstraaltje een geschenk. Dit werk heeft die dankbaarheid: het zoekt het licht tussen de stammen en vindt het.","xe":"In a dark forest, every ray of light feels like a gift. This work has that gratitude: it searches for the light between the trunks, and finds it."},{"id":"074","nr":"NV-074","thema":"abstract","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#85151b","pal":["#d30206","#750405","#7a0d11","#405f77","#6f2527"],"p":43,"t":"Gloed","d":"Rood en goud vloeien onder een blauwe hemel, als lava die afkoelt. Vurig en vol spanning. Een werk dat de temperatuur van een ruimte voelbaar verhoogt.","own":false,"e":"Red and gold flow beneath a blue sky, like lava cooling. Fiery and full of tension. A work that perceptibly raises the temperature of a room.","x":"Wat gloeit, heeft gebrand en is nog warm. Dit doek heeft de hitte van iets dat net tot rust komt: de spanning is er nog, het vuur is gebleven, maar het geweld is voorbij.","xe":"What glows has burned and is still warm. This canvas has the heat of something just coming to rest: the tension remains, the fire has stayed, but the violence has passed."},{"id":"075","nr":"NV-075","thema":"abstract","kleur":["rood","zwart"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#734339","pal":["#a81109","#1f181c","#65504a","#858071","#bca97c"],"p":43,"t":"De Vulkaan","d":"Rood, zwart, geel en grijs barsten over het doek. Nanny's titel zegt het al: een uitbarsting van kleur en energie, vastgelegd in groot formaat.","own":true,"e":"Red, black, yellow and grey erupt across the canvas. Nanny's title says it all: an eruption of colour and energy, captured on a large scale.","x":"Er is een kracht die zich niet laat temmen, en dat hoeft ook niet. Dit is energie in haar oervorm, ongeremd en levend: wat lang onder de oppervlakte broeide, komt eindelijk vrij.","xe":"There is a force that will not be tamed, and need not be. This is energy in its primal form, unrestrained and alive: what smouldered long beneath the surface is finally released."},{"id":"076","nr":"NV-076","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#3a859d","pal":["#227c98","#154370","#7aa7c9","#25a09a","#a0c8df"],"p":44,"t":"Vallei","d":"Blauw en groen met vonkjes oranje, als een vallei in het voorjaar. Fris en levendig, met een vrije toets. Een werk dat de natuur naar binnen haalt.","own":false,"e":"Blue and green with sparks of orange, like a valley in spring. Fresh and lively, with a free touch. A work that brings nature indoors.","x":"De eerste warme dag na de winter, als alles ineens groener lijkt. Dit werk heeft die frisse opluchting. Het haalt de vallei naar binnen, en het voorjaar mee.","xe":"The first warm day after winter, when everything suddenly seems greener. This work has that fresh relief. It brings the valley indoors, and spring along with it."},{"id":"077","nr":"NV-077","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#3f699a","pal":["#033c9e","#a3bcc0","#3675a6","#0a2e72","#2d4064"],"p":44,"t":"Scherven","d":"Blauwe vlakken in vele tinten, met wit en oker ertussen, als gebroken glas in het licht. Koel, levendig en ritmisch. Een werk vol beweging in een rustig palet.","own":false,"e":"Blue planes in many shades, with white and ochre between them, like broken glass in the light. Cool, lively and rhythmic. A work full of movement within a calm palette.","x":"Wat breekt, vangt het licht op een nieuwe manier. Er zit troost in die gedachte. Dit werk maakt van scherven iets schitterends, koel en levendig.","xe":"What breaks catches the light in a new way. There is consolation in that thought. This work makes something brilliant of shards, cool and alive."},{"id":"078","nr":"NV-078","thema":"stad","kleur":["blauw","zwart"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#546471","pal":["#424b58","#23262c","#5d7180","#7f9fae","#9ec2d1"],"p":45,"t":"Regenstad","d":"Gevels in grijs, zwart en ijsblauw, als een stad op een regenachtige middag. Stoer en ingetogen. Een werk met de melancholie en de schoonheid van de stad.","own":false,"e":"Façades in grey, black and ice blue, like a city on a rainy afternoon. Bold and restrained. A work with the melancholy and beauty of the city.","x":"Regen maakt een stad intiemer. Mensen schuilen, lichten weerspiegelen, alles wordt zachter. Dit werk heeft die mooie melancholie van een natte middag in de stad.","xe":"Rain makes a city more intimate. People shelter, lights reflect, everything grows softer. This work has the lovely melancholy of a wet afternoon in town."},{"id":"079","nr":"NV-079","thema":"stad","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#42698c","pal":["#45769f","#78a5c8","#1e334d","#25537c","#3b5c7e"],"p":45,"t":"De Bouwplaats","d":"Gebouwen in staalblauw en grijs rijzen op, half af en vol belofte. Nanny's titel maakt er een stad in wording van. Stoer en atmosferisch.","own":true,"e":"Buildings in steel blue and grey rise up, half finished and full of promise. Nanny's title makes it a city in the making. Bold and atmospheric.","x":"Alles wat af is, was ooit een bouwplaats. Ook een leven, ook een huis. Dit werk gaat over dat stadium van worden: rommelig, onaf, vol mogelijkheden.","xe":"Everything finished was once a building site. A life too, a home too. This work is about that stage of becoming: untidy, unfinished, full of possibility."},{"id":"080","nr":"NV-080","thema":"stad","kleur":["blauw","rood"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#997169","pal":["#233c7a","#cc322a","#ec9d3c","#889fa4","#ebcf81"],"p":46,"t":"New York City I en II","d":"Times Square in twee panelen: neon, wolkenkrabbers en gele taxi's in volle kleur. Op haar eigen website stonden ze als twee werken; samen vormen ze een sprekend paar. Een ode aan de stad die nooit slaapt.","own":true,"e":"Times Square in two panels: neon, skyscrapers and yellow cabs in full colour. On her own website they appeared as two works; together they form a striking pair. A tribute to the city that never sleeps.","x":"Wie ooit op Times Square stond, vergeet het licht niet, en het gevoel dat alles daar mogelijk is. Nanny schilderde die energie in twee panelen. Een herinnering aan dromen die groter zijn dan de stad.","xe":"Whoever has stood in Times Square does not forget the light, or the feeling that anything is possible there. Nanny painted that energy in two panels. A reminder of dreams larger than the city.","gaps":[[48.047,52.139]]},{"id":"081","nr":"NV-081","thema":"stad","kleur":["geel"],"ori":"liggend","type":"enkel","ar":1.5516,"avg":"#8b6b5c","pal":["#232548","#903950","#9d815c","#ded295","#d6c361"],"p":47,"t":"Daken","d":"Daken en gevels in roze, geel en blauw, kriskras over elkaar. Een stad als een puzzel, vrolijk en vol hoeken. Een werk dat leven brengt in een rustige ruimte.","own":false,"e":"Roofs and façades in pink, yellow and blue, criss-crossing each other. A city as a puzzle, cheerful and full of angles. A work that brings life to a calm space.","x":"Elk dak beschermt een eigen leven. Van boven gezien vormen ze samen een stad vol verhalen. Een werk dat de gezelligheid van samenleven laat zien.","xe":"Every roof shelters a life of its own. Seen from above, together they form a city full of stories. A work that shows the warmth of living side by side."},{"id":"082","nr":"NV-082","thema":"stad","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.5491,"avg":"#744342","pal":["#ab090a","#44466e","#221728","#a28459","#dec67c"],"p":47,"t":"Cars","d":"Auto's zijn overal, en bij Nanny zijn ze levend, snel en vol verhalen. Elke krachtige lijn en elke uitbarsting van rood draagt de hartslag van beweging en vrijheid. Een ode aan de machines die niet alleen onze straten bewegen, maar ook onze dromen en het ritme van alledag.","own":true,"e":"Cars are everywhere, and in Nanny's hands they are alive, fast and full of stories. Every bold line and every burst of red carries the heartbeat of movement and freedom. An ode to the machines that drive not only our streets, but our dreams and the rhythm of every day.","x":"Een eerste auto, een lange rit naar het zuiden, een wagen vol mensen die je liefhebt. Auto's dragen herinneringen. Dit werk eert die vrijheid, en alle wegen die we nog gaan rijden.","xe":"A first car, a long drive south, a car full of people you love. Cars carry memories. This work honours that freedom, and all the roads still to be travelled."},{"id":"083","nr":"NV-083","thema":"stad","kleur":["zwart","paars"],"ori":"vierkant","type":"enkel","ar":0.9847,"avg":"#897b82","pal":["#3b2630","#705d69","#c9c0c4","#aba0a6","#d7d1d1"],"p":48,"t":"Perron","d":"Een trein glijdt onder een overkapping door, in grijs, wit en paars. Het werk vangt het moment van vertrek of aankomst. Vol stedelijke sfeer.","own":false,"e":"A train glides beneath a canopy, in grey, white and purple. The work captures the moment of departure or arrival. Full of urban atmosphere.","x":"Op een perron gebeurt het: afscheid, weerzien, vertrek naar iets nieuws. Dit werk vangt die beladen seconden, als de trein net binnenrolt of net vertrekt.","xe":"It happens on a platform: farewell, reunion, departure towards something new. This work captures those charged seconds, as the train is just arriving or just pulling away."},{"id":"084","nr":"NV-084","thema":"stad","kleur":["zwart","rood"],"ori":"vierkant","type":"enkel","ar":0.9809,"avg":"#56584b","pal":["#11180f","#71745d","#503432","#b3afb0","#5c8d68"],"p":48,"t":"Het Uur","d":"Een klok met rode wijzers, witte bellen en een vlak groen. Grafisch, met een vleugje humor. Linksonder gesigneerd.","own":false,"e":"A clock with red hands, white bells and a plane of green. Graphic, with a touch of humour. Signed lower left.","x":"De tijd is het enige wat we allemaal even veel hebben, en nooit genoeg. Dit werk kijkt er met een glimlach naar. Een knipoog aan de muur, om af en toe te vergeten hoe laat het is.","xe":"Time is the only thing we all have equally, and never enough of. This work looks at it with a smile. A wink on the wall, to occasionally forget what time it is."},{"id":"085","nr":"NV-085","thema":"stad","kleur":["oranje","zwart"],"ori":"vierkant","type":"enkel","ar":0.9847,"avg":"#7b6764","pal":["#262030","#9d7d6c","#6a4a3e","#b7a198","#c5cad3"],"p":48,"t":"De Oude Poort","d":"Een smalle doorgang tussen hoge muren in oker, blauw en bruin, met licht aan het eind. Nanny's titel roept een historische stad op. Een werk met diepte en sfeer.","own":true,"e":"A narrow passage between high walls in ochre, blue and brown, with light at the end. Nanny's title evokes a historic town. A work of depth and atmosphere.","x":"Een oude poort heeft talloze mensen zien passeren, elk met een eigen verhaal. Aan het eind brandt licht. Een werk over doorgaan, en over wat ons verbindt met wie ons voorging.","xe":"An old gate has seen countless people pass, each with a story of their own. At the end, there is light. A work about carrying on, and about what binds us to those who went before."},{"id":"086","nr":"NV-086","thema":"stad","kleur":["zwart","oranje"],"ori":"vierkant","type":"enkel","ar":0.9809,"avg":"#584740","pal":["#130b08","#331c13","#6a5143","#9c897d","#c4c1c0"],"p":48,"t":"Gewelven","d":"Bogen en zuilen in bruin, wit en roest, als de resten van een oud bouwwerk. Vol karakter en geschiedenis. Een werk dat goed samengaat met klassieke interieurs.","own":false,"e":"Arches and columns in brown, white and rust, like the remains of an old building. Full of character and history. A work that sits well in classic interiors.","x":"Wat ooit stond, laat sporen na die mooier kunnen zijn dan het geheel. Bogen zonder dak, zuilen zonder tempel. Dit werk eert wat blijft van wat voorbij is.","xe":"What once stood leaves traces that can be more beautiful than the whole. Arches without a roof, columns without a temple. This work honours what remains of what has passed."},{"id":"087","nr":"NV-087","thema":"stad","kleur":["blauw","groen"],"ori":"vierkant","type":"enkel","ar":0.9847,"avg":"#226665","pal":["#187c5f","#023259","#012f54","#67bc8f","#0d324f"],"p":49,"t":"Zondag","d":"Witte was wappert aan een lijn boven een felgroen grasveld, onder een donkerblauwe lucht. Een alledaags moment, met grote eenvoud geschilderd. Een werk vol zomergevoel en nostalgie.","own":false,"e":"White laundry flutters on a line above a bright green lawn, under a dark blue sky. An everyday moment, painted with great simplicity. A work full of summer feeling and nostalgia.","x":"Was aan de lijn, een groen gazon, een lucht die op regen wacht: geen bijzonder moment, en daarom zo dierbaar. Dit werk eert het gewone geluk van een zondag thuis.","xe":"Washing on the line, a green lawn, a sky waiting for rain: no special moment, and that is why it is so dear. This work honours the ordinary happiness of a Sunday at home."},{"id":"088","nr":"NV-088","thema":"landschap","kleur":["blauw","rood"],"ori":"vierkant","type":"enkel","ar":0.9809,"avg":"#d7c7c7","pal":["#ecd8d2","#e1cfcb","#a89ca9","#ecdeda","#e7d7d2"],"p":49,"t":"Riviera","d":"Roze en turquoise parasols op een zacht roze grond. Licht, luchtig en elegant: de zomer aan de kust in één beeld. Een van de meest verfijnde werken in de collectie.","own":false,"e":"Pink and turquoise parasols on a soft pink ground. Light, airy and elegant: summer on the coast in a single image. One of the most refined works in the collection.","x":"Een zomer waarin niets moest. Parasols in de wind, voeten in het zand, een dag die niet op hoefde te houden. Dit werk is die zomer, licht en elegant, voor altijd.","xe":"A summer in which nothing was required. Parasols in the wind, feet in the sand, a day that need not end. This work is that summer, light and elegant, forever."},{"id":"089","nr":"NV-089","thema":"stad","kleur":["zwart","blauw"],"ori":"vierkant","type":"enkel","ar":0.9847,"avg":"#4e5158","pal":["#0d1630","#6a6054","#323137","#7195bd","#b0a192"],"p":49,"t":"De Watervilla","d":"Een villa aan het water in oker, paars en nachtblauw, met lichten die in het water spiegelen. Avond aan de waterkant, rustig en sfeervol.","own":true,"e":"A villa by the water in ochre, purple and midnight blue, its lights reflected in the water. Evening at the waterside, calm and atmospheric.","x":"Er is geen rustiger beeld dan licht dat in stil water spiegelt. Een huis aan het water, de avond die valt, een venster nog verlicht. Dit werk ademt het verlangen naar zo'n plek.","xe":"There is no calmer image than light reflected in still water. A house on the water, evening falling, a window still lit. This work breathes the longing for such a place."},{"id":"090","nr":"NV-090","thema":"abstract","kleur":["rood","paars"],"ori":"vierkant","type":"enkel","ar":0.9809,"avg":"#9b7e94","pal":["#a97592","#ca9eb3","#4e3649","#d8bbc9","#a1a0b5"],"p":49,"t":"Geen Beeld","d":"Een zacht roze vlak, omlijst door donker en blauw. Nanny's ironische titel maakt van de leegte het onderwerp. Een werk over stilte, verrassend modern.","own":true,"e":"A soft pink plane, framed by dark and blue. Nanny's ironic title makes emptiness the subject. A work about silence, surprisingly modern.","x":"In deze zachte leegte zit juist iets kostbaars: ruimte om zelf te dromen. Wat u erin ziet, hangt af van de dag, de stemming, het licht. Een werk dat niets oplegt en alles toelaat.","xe":"This soft emptiness holds something precious: room to dream for yourself. What you see in it depends on the day, the mood, the light. A work that imposes nothing and allows everything."},{"id":"091","nr":"NV-091","thema":"landschap","kleur":["oranje","rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#9c8361","pal":["#b8965b","#c1bb8c","#7a6860","#634845","#a87955"],"p":50,"t":"Santorini","d":"De geest van Santorini in krachtige, expressieve streken: zonovergoten kliffen die de diepe Egeïsche Zee raken. Zacht paars, helder oker en turquoise spiegelen de contrasten van het eiland, zee en steen, geschiedenis en stilte. Meer dan een landschap is het een gevoel: een warme herinnering, een moment van rust, een uitnodiging om te zwerven. Het licht van de Middellandse Zee, in huis.","own":true,"e":"The spirit of Santorini in bold, expressive strokes: sunlit cliffs meeting the deep Aegean. Soft purples, bright ochres and turquoise echo the island's contrasts, sea and stone, history and stillness. More than a landscape, it is a feeling: a warm memory, a moment of calm, an invitation to wander. The light of the Mediterranean, brought home.","x":"Sommige reizen neem je mee voor de rest van je leven. Het licht op de kliffen, het blauw van de zee, de stilte bij zonsondergang. Dit werk houdt zo'n reis levend, in uw eigen huis.","xe":"Some journeys stay with you for the rest of your life. The light on the cliffs, the blue of the sea, the stillness at sunset. This work keeps such a journey alive, in your own home."},{"id":"092","nr":"NV-092","thema":"landschap","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#ef3031","pal":["#f70000","#f6313e","#ed8872","#f70806","#e40513"],"p":50,"t":"De Rode Vlakte","d":"Een vlakte van rood en roze die zich eindeloos uitstrekt. Warm en weids, met een zachte, bijna tastbare kleur.","own":true,"e":"A plain of red and pink stretching out endlessly. Warm and wide, with a soft, almost tangible colour.","x":"Een vlakte die nergens eindigt, geeft je adem. Dit rood is geen alarm, maar warmte: een landschap om in op te gaan. Een werk dat ruimte maakt in een hoofd vol drukte.","xe":"A plain that never ends gives you breath. This red is no alarm, but warmth: a landscape to lose yourself in. A work that makes room in a busy mind."},{"id":"093","nr":"NV-093","thema":"stad","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#5d483d","pal":["#172336","#891d17","#3f5751","#c5891d","#5e8894"],"p":51,"t":"Dorpsstraat","d":"Een straat met gele huizen en rode daken, verlicht door de zon. Gezellig, kleurrijk en vol leven. Een werk dat thuiskomen uitstraalt.","own":false,"e":"A street of yellow houses with red roofs, lit by the sun. Cosy, colourful and full of life. A work that feels like coming home.","x":"Er is één straat waar je altijd thuiskomt, ook als je er al jaren niet woont. Dit werk heeft die warmte: gele huizen, rode daken, een middag die naar vroeger ruikt.","xe":"There is one street where you always come home, even if you have not lived there for years. This work has that warmth: yellow houses, red roofs, an afternoon that smells of the past."},{"id":"094","nr":"NV-094","thema":"stad","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#772b19","pal":["#170d0e","#820704","#d66428","#6f2a17","#d67d4e"],"p":51,"t":"Avondgloed","d":"Rode gebouwen tegen een oranje lucht, een stad in de laatste zon. Warm en dramatisch. Een werk met de gloed van een zomeravond.","own":false,"e":"Red buildings against an orange sky, a city in the last sun. Warm and dramatic. A work with the glow of a summer evening.","x":"Het mooiste licht valt op het eind van de dag, als de stad gloeit en de haast eruit is. Dit doek houdt die zomeravond vast, warm en een beetje dramatisch.","xe":"The finest light falls at the end of the day, when the city glows and the rush has gone out of it. This canvas holds that summer evening, warm and a little dramatic."},{"id":"095","nr":"NV-095","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":2.6062,"avg":"#689bdf","pal":["#4491e1","#134ed1","#88b9e6","#b8d0e6","#cadbe9"],"p":52,"t":"Gewelf in Blauw","d":"Bogen in wit en blauw, als golven of glazen gewelven. Fris, ritmisch en licht. Een smal werk dat mooi is boven een dressoir of bed.","own":false,"e":"Arches in white and blue, like waves or glass vaults. Fresh, rhythmic and light. A narrow work that is lovely above a sideboard or bed.","x":"Golven of gewelven: het blijft open. Dat is het mooie van dit werk. Het tilt de blik omhoog en geeft een ruimte iets lichts, iets hemels.","xe":"Waves or vaults: it stays open. That is the beauty of this work. It lifts the gaze upward and gives a space something light, something heavenly."},{"id":"096","nr":"NV-096","thema":"stad","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.3184,"avg":"#4f83d2","pal":["#a1bae2","#1a71d5","#5693d9","#134dbb","#4976cd"],"p":52,"t":"Monument in Blue","d":"Een gebouw in vele tinten blauw met een deur linksonder, monumentaal en rustig. Een werk dat stilte en waardigheid uitstraalt.","own":true,"e":"A building in many shades of blue with a door lower left, monumental and calm. A work that radiates stillness and dignity.","x":"Sommige gebouwen zijn meer dan steen. Ze dragen herinnering, waardigheid, de stilte van wie er binnen ging. Nanny's monument in blauw heeft die ernst, en die rust.","xe":"Some buildings are more than stone. They carry memory, dignity, the stillness of those who entered. Nanny's monument in blue has that gravity, and that calm."},{"id":"097","nr":"NV-097","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.3184,"avg":"#346384","pal":["#73a7b6","#38728f","#08386a","#02346b","#38455a"],"p":52,"t":"Dorp van Boven","d":"Huizen als blokken in blauw, wit en grijs, gezien van bovenaf. Een dorp teruggebracht tot vorm en licht. Koel en harmonieus.","own":false,"e":"Houses like blocks in blue, white and grey, seen from above. A village reduced to form and light. Cool and harmonious.","x":"Van boven ziet alles er ordelijker uit dan het voelt. Er zit troost in dat perspectief: de drukte van een dorp wordt vorm en licht. Een rustig werk om je gedachten aan te ordenen.","xe":"From above, everything looks more orderly than it feels. There is consolation in that perspective: the bustle of a village becomes form and light. A calm work to order your thoughts by."},{"id":"098","nr":"NV-098","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.3128,"avg":"#6b626d","pal":["#786f7f","#614f59","#2a3158","#afa48f","#9b8a77"],"p":53,"t":"Stilleven met Kruik","d":"Een kruik, vazen en flessen in violet, oker en blauw. Een klassiek genre in een moderne, vrije uitvoering. Mooi in een eetkamer.","own":false,"e":"A jug, vases and bottles in violet, ochre and blue. A classical genre in a modern, free execution. Lovely in a dining room.","x":"Een stilleven is een eerbetoon aan de dingen waarmee we leven. Een kruik, een vaas, een fles op tafel. Nanny gaf die gewone voorwerpen kleur en waardigheid, en daarmee het dagelijks leven ook.","xe":"A still life is a tribute to the things we live with. A jug, a vase, a bottle on the table. Nanny gave those ordinary objects colour and dignity, and with them, everyday life too."},{"id":"099","nr":"NV-099","thema":"abstract","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.3184,"avg":"#4b6c61","pal":["#121e31","#355358","#408f80","#989c74","#b3c482"],"p":53,"t":"Stilleven in Groen","d":"Vruchten en een schaal in groen, geel en blauw, los en levendig geschilderd. Een fris, eigentijds stilleven.","own":false,"e":"Fruit and a bowl in green, yellow and blue, painted loosely and vividly. A fresh, contemporary still life.","x":"Fruit op een schaal, de tafel gedekt, iemand die zo binnenkomt. Dit werk heeft de belofte van gastvrijheid. Fris, levendig en vol goede dagen.","xe":"Fruit in a bowl, the table laid, someone about to walk in. This work holds the promise of hospitality. Fresh, lively and full of good days."},{"id":"100","nr":"NV-100","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":2.601,"avg":"#617c6c","pal":["#c8aa6a","#12476d","#799274","#0e6874","#54715c"],"p":53,"t":"Aan het Water","d":"Een smal werk met een huis aan het water tussen groen en geel. Een rustig zomerbeeld, als een herinnering aan een vakantie.","own":false,"e":"A narrow work with a house by the water between green and yellow. A quiet summer scene, like the memory of a holiday.","x":"Ieder heeft een huis aan het water in zijn hoofd: een vakantie, een droom, een plek van vroeger. Dit kleine werk opent dat venster, rustig en vertrouwd.","xe":"Everyone carries a house by the water in their mind: a holiday, a dream, a place from the past. This small work opens that window, calm and familiar."},{"id":"101","nr":"NV-101","thema":"landschap","kleur":["blauw","geel"],"ori":"vierkant","type":"tweeluik","ar":1.0394,"avg":"#526a73","pal":["#014096","#dfc761","#061a45","#338bac","#511628"],"p":54,"t":"Bergen","d":"Een tweeluik met bergen in blauw, geel en rood, helder en krachtig. De panelen lopen door als één panorama. Op zijn best op een brede wand.","own":false,"e":"A diptych of mountains in blue, yellow and red, clear and powerful. The panels continue as a single panorama. At its best on a wide wall.","x":"Een bergpanorama doet iets met je: het maakt je klein, en tegelijk groots. Dit tweeluik geeft een wand dat uitzicht, en de bewoner even die adem van de hoogte.","xe":"A mountain panorama does something to you: it makes you small, and at the same time great. This diptych gives a wall that view, and its owner, for a moment, the breath of the heights.","gaps":[[48.075,52.174]]},{"id":"102","nr":"NV-102","thema":"landschap","kleur":["rood"],"ori":"vierkant","type":"tweeluik","ar":1.0384,"avg":"#b27857","pal":["#b80203","#dddebc","#a74c2c","#ddc263","#8cc29e"],"p":55,"t":"Township","d":"Een tweeluik over een township in Kaapstad, Zuid-Afrika, en een zeer persoonlijk eerbetoon aan de geest van die gemeenschap. In krachtige kleur en gelaagde texturen vangt Nanny zowel de strijd als de veerkracht die het leven daar vormen. Elk paneel spreekt van het dagelijks bestaan en van hoop die standhoudt. Geen werk over een plek alleen, maar over de verhalen en gevoelens die in elke kleur besloten liggen.","own":true,"e":"A diptych of a township in Cape Town, South Africa, and a deeply personal tribute to the spirit of that community. In bold colour and layered texture Nanny captures both the struggle and the resilience that shape life there. Each panel speaks of daily existence and of hope that endures. Not a work about a place alone, but about the stories and feelings held within every colour.","x":"Waar het leven zwaar is, staat het vaak het sterkst in bloei. Nanny schilderde die gemeenschap met respect en liefde. Een werk dat eraan herinnert hoeveel waardigheid er in gewone levens schuilt.","xe":"Where life is hard, it often blossoms most strongly. Nanny painted that community with respect and love. A work that reminds us how much dignity lies within ordinary lives.","gaps":[[47.998,52.126]]},{"id":"103","nr":"NV-103","thema":"figuur","kleur":["geel","blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#788e61","pal":["#143447","#467772","#9bb374","#e6ce49","#f2e468"],"p":56,"t":"The Presidents","d":"Een tweeluik met gezichten uitgehouwen in rots, in geel, groen en blauw. Nanny's eigen, kleurrijke kijk op Mount Rushmore.","own":true,"e":"A diptych of faces carved in rock, in yellow, green and blue. Nanny's own colourful take on Mount Rushmore.","x":"Gezichten in steen, gemaakt om eeuwen te overleven. Nanny keek ernaar met kleur en met humor. Een werk over wat we bewaren, wie we eren, en hoe we herinnerd willen worden.","xe":"Faces in stone, made to outlast the centuries. Nanny looked at them with colour and with humour. A work about what we preserve, whom we honour, and how we wish to be remembered.","gaps":[[48.047,52.139]]},{"id":"104","nr":"NV-104","thema":"stad","kleur":["blauw","rood"],"ori":"vierkant","type":"tweeluik","ar":1.0397,"avg":"#91847e","pal":["#4f758f","#a1161a","#7db3ba","#d9ddba","#d5c370"],"p":57,"t":"Nine Eleven","d":"Een tweeluik met twee torens in vlammen. Een indringend werk, door Nanny zelf zo getiteld, over een dag die de wereld veranderde.","own":true,"e":"A diptych of two towers in flames. A searing work, titled by Nanny herself, about a day that changed the world.","x":"Er zijn dagen die niemand vergeet die ze heeft meegemaakt. Nanny schilderde er een, zonder sensatie, met ernst. Een werk dat herinnert, en daarmee eert.","xe":"There are days no one forgets who lived through them. Nanny painted one of them, without sensation, with gravity. A work that remembers, and in doing so honours.","gaps":[[47.938,52.062]]},{"id":"105","nr":"NV-105","thema":"figuur","kleur":["blauw","geel"],"ori":"liggend","type":"enkel","ar":1.5338,"avg":"#6ea5a3","pal":["#ece0a0","#0497b0","#0e5179","#98c9c1","#4a9ab6"],"p":58,"t":"Drie Gratiën","d":"Drie vrouwenfiguren in turquoise en geel, dicht bij elkaar. Een klassiek thema uit de kunstgeschiedenis, vertaald in haar eigen moderne kleuren.","own":false,"e":"Three female figures in turquoise and yellow, close together. A classical theme from art history, translated into her own modern colours.","x":"Drie vrouwen die elkaar vasthouden: een van de oudste beelden van vriendschap en gratie. Dit werk geeft het een eigen tijd en kleur. Voor wie weet wat zusterschap betekent.","xe":"Three women holding one another: one of the oldest images of friendship and grace. This work gives it its own time and colour. For anyone who knows what sisterhood means."},{"id":"106","nr":"NV-106","thema":"figuur","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.5338,"avg":"#327087","pal":["#0b91c2","#014e8e","#2f3541","#8f9362","#84bfb4"],"p":58,"t":"Together","d":"Eenvoudige figuren, zachte kleuren, en daarin alles wat ertoe doet. Together is een stil eerbetoon aan de banden die ons dragen door de zwaarste momenten van het leven: vertrouwen, liefde, en naast elkaar blijven lopen, ook het onbekende in.","own":true,"e":"Simple figures, gentle colours, and within them everything that matters. Together is a quiet tribute to the bonds that carry us through life's hardest moments: trust, love, and walking on side by side, even into the unknown.","x":"Wie samen door een moeilijke tijd is gegaan, weet dat de stilte tussen twee mensen soms alles zegt. Dit werk bewaart zo'n stilte. Het hoort in een huis waar iemand naast u staat.","xe":"Whoever has come through a hard time together knows that the silence between two people can say everything. This work keeps such a silence. It belongs in a home where someone stands beside you."},{"id":"107","nr":"NV-107","thema":"figuur","kleur":["blauw"],"ori":"vierkant","type":"enkel","ar":1.0178,"avg":"#4d629b","pal":["#1280d8","#083d96","#982334","#6c8bb9","#97c0d4"],"p":59,"t":"Levensloop","d":"We veranderen, maar onze kern blijft dezelfde. Levensloop is een van Nanny's meest persoonlijke werken en weerspiegelt haar eigen reis. Vloeiende lijnen, cirkelvormen en een rode figuur staan voor de constante kern in ons, te midden van alles wat verandert. In diep blauw, zacht wit en warm rood spreekt het van identiteit, verandering en stille kracht; een werk dat uitnodigt tot bezinning en houvast geeft.","own":true,"e":"We change, yet our essence stays the same. Life Cycle is one of Nanny's most personal works and reflects her own journey. Flowing lines, circular forms and a red figure stand for the constant core within us, amid everything that changes. In deep blue, soft white and warm red it speaks of identity, change and quiet strength; a work that invites reflection and offers a sense of grounding.","x":"Een leven is geen rechte lijn maar een beweging in cirkels: terugkeren, veranderen, opnieuw beginnen. En in het midden iets dat blijft. Dit werk geeft dat iets een kleur: warm rood.","xe":"A life is not a straight line but a movement in circles: returning, changing, beginning again. And at the centre, something that remains. This work gives that something a colour: warm red."},{"id":"108","nr":"NV-108","thema":"figuur","kleur":["blauw","rood"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#48385a","pal":["#9c1d04","#0151b7","#0053b7","#251d43","#765856"],"p":60,"t":"Rug","d":"Een vrouwenrug in oranje en roodbruin tegen helder blauw. Warm, intiem en met grote eenvoud geschilderd.","own":false,"e":"A woman's back in orange and reddish brown against bright blue. Warm, intimate and painted with great simplicity.","x":"Een rug is het kwetsbaarste wat iemand je kan laten zien: het deel dat je niet zelf beschermt. Dit werk kijkt er teder naar, warm en zonder oordeel.","xe":"A back is the most vulnerable thing a person can show you: the part they cannot protect themselves. This work looks at it tenderly, warm and without judgement."},{"id":"109","nr":"NV-109","thema":"figuur","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#0a51b6","pal":["#065fcc","#072187","#1481d7","#0344b9","#1041a4"],"p":60,"t":"Women in Blue","d":"Een van Nanny's meest persoonlijke werken: een intiem portret van stille kracht en introspectie, geschilderd naar model. De figuur is gehuld in diep blauw en heeft geen gezicht; ze spreekt van de moed die in stilte en zelfreflectie ligt. Met minimale vorm en kleur maakte Nanny van blauw een emotie, en liet ze zien hoe zij de wereld zag: met diepgang, mededogen en respect voor het onuitgesprokene.","own":true,"e":"One of Nanny's most personal works: an intimate portrait of quiet strength and introspection, painted from a live model. The figure is cloaked in deep blue and has no face; she speaks of the courage that lies in stillness and self-reflection. With minimal form and colour Nanny turned blue into emotion, revealing how she saw the world: with depth, compassion and respect for the unspoken.","x":"Er is een stilte die geen leegte is, maar volheid. Een mens die bij zichzelf is. Dit werk heeft die stilte, en geeft haar door aan wie ernaar kijkt.","xe":"There is a silence that is not emptiness, but fullness. A person at home within herself. This work has that silence, and passes it on to whoever looks."},{"id":"110","nr":"NV-110","thema":"figuur","kleur":["oranje","geel"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#cc9a62","pal":["#cc9547","#d4d0c9","#ceb884","#b54b28","#f1d25e"],"p":61,"t":"Reflected Moment","d":"Een eerbetoon aan de stille pauzes waarin we onszelf werkelijk zien. De figuur, geschilderd naar model en gehuld in warme tinten, is tegelijk geaard en ver weg, gedragen door de subtiele energie van stilte. Een werk over de ruimte tussen wie we zijn, wie we waren en wie we worden, vol van Nanny's warmte, eerlijkheid en liefde voor de schoonheid van alledag.","own":true,"e":"A tribute to the quiet pauses in which we truly see ourselves. The figure, painted from a live model and wrapped in warm tones, is grounded and distant at once, carried by the subtle energy of stillness. A work about the space between who we are, who we were and who we are becoming, full of Nanny's warmth, honesty and love for everyday beauty.","x":"Soms zie je jezelf ineens helder: in een spiegel, in een blik van een ander, in een stil uur. Dit werk gaat over dat ogenblik van herkenning, en de zachtheid waarmee we het mogen ontvangen.","xe":"Sometimes you suddenly see yourself clearly: in a mirror, in another's glance, in a quiet hour. This work is about that moment of recognition, and the gentleness with which we may receive it."},{"id":"111","nr":"NV-111","thema":"figuur","kleur":["geel","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#988b69","pal":["#c2a153","#2f477a","#917f54","#e0cd95","#d4b972"],"p":61,"t":"Liggend Naakt","d":"Een liggende vrouw in geel en zandkleur op blauw. Een van de oudste motieven uit de kunst, in haar eigen kleuren en met haar eigen lichtheid.","own":false,"e":"A reclining woman in yellow and sand on blue. One of the oldest motifs in art, in her own colours and with her own lightness.","x":"Rusten is ook een vorm van leven. Een lichaam dat zich overgeeft aan warmte en licht. Dit werk heeft die zorgeloze kalmte, eeuwenoud en toch eigentijds.","xe":"Resting is also a way of living. A body surrendering to warmth and light. This work has that carefree calm, centuries old and yet contemporary."},{"id":"112","nr":"NV-112","thema":"figuur","kleur":["oranje","rood"],"ori":"vierkant","type":"tweeluik","ar":1.0376,"avg":"#c55c18","pal":["#e92e05","#e79a0e","#822d18","#be691d","#edc044"],"p":62,"t":"Rood en Goud","d":"Een tweeluik met twee vrouwenfiguren in vuurrood en goudgeel. Sensueel en krachtig, met een sterke, vrije lijn.","own":false,"e":"A diptych of two female figures in fiery red and golden yellow. Sensual and powerful, with a strong, free line.","x":"Vuur en goud, twee vrouwen vol eigen kracht. Dit tweeluik viert vrouwelijkheid zonder verontschuldiging: zinnelijk, zelfverzekerd, vrij.","xe":"Fire and gold, two women full of their own strength. This diptych celebrates femininity without apology: sensual, self-assured, free.","gaps":[[48.034,52.15]]},{"id":"113","nr":"NV-113","thema":"figuur","kleur":["blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0365,"avg":"#8b8c7c","pal":["#54b7d0","#eba340","#8a888c","#614153","#efbc48"],"p":63,"t":"Turned Away I en II","d":"Twee vrouwen, geschilderd naar model en van achteren gezien. Het rechterpaneel, Turned Away, lag Nanny na aan het hart: stralend oker tegen zacht lavendel, de gloeiende huid warm tegen de koele achtergrond. Ze koos voor houding en kleur in plaats van een gezicht, en vierde vrouwelijkheid als aanwezigheid en expressie. Kwetsbaar en zelfverzekerd tegelijk; links beantwoord door een koeler tegenbeeld in turquoise.","own":false,"e":"Two women, painted from a live model and seen from behind. The right-hand panel, Turned Away, was close to Nanny's heart: radiant ochre against soft lavender, the glowing skin warm against the cool background. She chose posture and colour over a face, celebrating femininity as presence and expression. Vulnerable and self-assured at once; answered on the left by a cooler counterpart in turquoise.","x":"Wie zich afwendt, toont iets anders dan een gezicht: een houding, een geheim, een eigen wereld. Deze twee vrouwen vragen niets en zeggen veel. Een werk vol stille zelfstandigheid.","xe":"Whoever turns away reveals something other than a face: a posture, a secret, a world of her own. These two women ask for nothing and say a great deal. A work full of quiet independence.","gaps":[[48.052,52.134]]},{"id":"114","nr":"NV-114","thema":"figuur","kleur":["blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#3372b8","pal":["#0d92db","#6bb3e0","#0849a2","#0249b5","#872c4e"],"p":64,"t":"De Blik","d":"Een tweeluik met een gezicht in blauw en ogen die je door de kamer volgen. Intens en onvergetelijk, een werk dat de ruimte bezielt.","own":false,"e":"A diptych of a face in blue with eyes that follow you around the room. Intense and unforgettable, a work that animates a space.","x":"Sommige blikken laten je niet los. Ze kijken niet naar je, maar in je. Dit werk heeft die intensiteit; het bezielt een kamer, en blijft je volgen in je gedachten.","xe":"Some gazes do not let you go. They look not at you, but into you. This work has that intensity; it inhabits a room, and keeps following you in your thoughts.","gaps":[[48.047,52.139]]},{"id":"115","nr":"NV-115","thema":"figuur","kleur":["blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0397,"avg":"#547792","pal":["#233b5b","#05437f","#458eb4","#e1d7c4","#dcc6af"],"p":65,"t":"Manly Torso I en II","d":"Nanny's moderne eerbetoon aan tijdloze kracht, geschilderd naar een man die poseerde als een Romeins torso. Geïnspireerd door klassiek beeldhouwwerk zocht ze het evenwicht tussen macht en kwetsbaarheid: links ivoor als marmer, rechts in vloeiende lijnen en gelaagd blauw. Een werk over volharding en breekbaarheid, dat ons laat nadenken over wat ware kracht is. Waardig, diepgaand, en haar na aan het hart.","own":false,"e":"Nanny's modern tribute to timeless strength, painted from a man posing as a Roman torso. Inspired by classical sculpture, she sought the balance between power and vulnerability: ivory like marble on the left, flowing lines and layered blues on the right. A work about endurance and fragility that asks what true strength really is. Dignified, profound, and close to her heart.","x":"Kracht is niet hetzelfde als hardheid. De sterkste mensen zijn vaak ook de meest kwetsbare. Deze twee torso's vertellen dat verhaal: marmer naast een lijn, blijvend naast voorbijgaand.","xe":"Strength is not the same as hardness. The strongest people are often also the most vulnerable. These two torsos tell that story: marble beside a line, the lasting beside the passing.","gaps":[[47.938,52.062]]},{"id":"116","nr":"NV-116","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"enkel","ar":1.9369,"avg":"#947b6e","pal":["#830a12","#deb893","#55bbb4","#99606b","#e4d281"],"p":66,"t":"Flamingo","d":"Roze, rood en teal in vloeiende vormen, sierlijk en exotisch. Een werk met de elegantie van een vogel in beweging.","own":false,"e":"Pink, red and teal in flowing forms, graceful and exotic. A work with the elegance of a bird in motion.","x":"Elegantie is een manier van bewegen door de wereld: licht, zeker, zonder haast. Dit werk heeft die gratie, als een vogel die even op één poot staat voordat hij opvliegt.","xe":"Elegance is a way of moving through the world: light, assured, unhurried. This work has that grace, like a bird standing on one leg for a moment before it takes flight."},{"id":"117","nr":"NV-117","thema":"figuur","kleur":["blauw"],"ori":"vierkant","type":"enkel","ar":1.0324,"avg":"#6c6093","pal":["#1e3694","#6479ba","#cf7e51","#664487","#c4a09f"],"p":66,"t":"Duet","d":"Twee figuren in paars, blauw en oranje, dicht tegen elkaar aan. Een werk over verbondenheid en intimiteit.","own":false,"e":"Two figures in purple, blue and orange, close against each other. A work about connection and intimacy.","x":"Twee mensen die op elkaar zijn ingespeeld, bewegen zonder woorden. Dit werk is zo'n duet: dichtbij, vertrouwd, in harmonie. Een geschenk voor een gedeeld huis.","xe":"Two people attuned to each other move without words. This work is such a duet: close, familiar, in harmony. A gift for a shared home."},{"id":"118","nr":"NV-118","thema":"figuur","kleur":["rood","blauw"],"ori":"vierkant","type":"enkel","ar":1.036,"avg":"#5f2b4c","pal":["#cb0203","#5c0a14","#1556af","#322a54","#3c92d7"],"p":66,"t":"De Schaduw","d":"Een rode figuur met een blauwe schaduw die meekijkt. Nanny's titel opent een vraag: wie zijn we, en wat volgt ons? Een groot, beschouwend werk.","own":true,"e":"A red figure with a blue shadow looking on. Nanny's title opens a question: who are we, and what follows us? A large, reflective work.","x":"Iedereen draagt iets mee dat meekijkt: een herinnering, een ander ik, iemand die er niet meer is. Dit grote werk nodigt uit om stil te staan bij wat ons volgt, en bij wat ons draagt.","xe":"Everyone carries something that watches along: a memory, another self, someone who is no longer here. This large work invites you to pause on what follows us, and on what carries us."},{"id":"119","nr":"NV-119","thema":"figuur","kleur":["blauw","rood"],"ori":"vierkant","type":"enkel","ar":0.9863,"avg":"#865662","pal":["#2a71ba","#f11005","#f9a91a","#453064","#7ba7b2"],"p":67,"t":"Gestalte","d":"Een figuur opgebouwd uit rode, blauwe en oranje vlakken, expressief en vol energie. Figuur en abstractie gaan hier naadloos in elkaar over.","own":false,"e":"A figure built from red, blue and orange planes, expressive and full of energy. Figure and abstraction merge seamlessly here.","x":"Een mens is meer dan zijn contouren. Hier valt een gestalte uiteen in kleur, en wordt juist daardoor levendiger. Een werk over hoe veelkleurig ieder van ons van binnen is.","xe":"A person is more than their outline. Here a figure falls apart into colour, and becomes more alive because of it. A work about how many-coloured each of us is within."},{"id":"120","nr":"NV-120","thema":"figuur","kleur":["blauw","rood"],"ori":"vierkant","type":"enkel","ar":0.998,"avg":"#979e99","pal":["#82908d","#636566","#a2b5b0","#d9dad4","#cfc3ad"],"p":68,"t":"Gezichten","d":"Gezichten in groen, rood en grijs vloeien in elkaar over, fascinerend en een beetje mysterieus. Een werk dat bij elke blik iemand anders laat zien.","own":false,"e":"Faces in green, red and grey flow into one another, fascinating and a little mysterious. A work that shows someone different with every look.","x":"Wie lang leeft, draagt veel gezichten in zich mee: van ouders, vrienden, geliefden, van zichzelf op andere leeftijden. Dit werk laat ze in elkaar overvloeien, mysterieus en vertrouwd.","xe":"Whoever lives long carries many faces within: parents, friends, loved ones, oneself at other ages. This work lets them flow into one another, mysterious and familiar."},{"id":"121","nr":"NV-121","thema":"figuur","kleur":["zwart","blauw"],"ori":"vierkant","type":"tweeluik","ar":0.9194,"avg":"#3b4048","pal":["#444047","#1a191f","#70868e","#0e182a","#372522"],"p":69,"t":"Maskers","d":"Een tweeluik met gestileerde gezichten in diep blauw en bruin, geïnspireerd op Afrikaanse maskers. Krachtig en tijdloos.","own":false,"e":"A diptych of stylised faces in deep blue and brown, inspired by African masks. Powerful and timeless.","x":"Een masker verbergt en onthult tegelijk. Het toont wat een gemeenschap eert, wat ze vreest, wat ze doorgeeft. Dit tweeluik draagt die eeuwenoude kracht met respect en ingetogenheid.","xe":"A mask conceals and reveals at once. It shows what a community honours, what it fears, what it hands down. This diptych carries that ancient power with respect and restraint.","gaps":[[48.063,52.141]]},{"id":"122","nr":"NV-122","thema":"figuur","kleur":["paars","rood"],"ori":"liggend","type":"enkel","ar":1.6063,"avg":"#9b799c","pal":["#af7aa3","#3e2c68","#dd95a6","#a19fb8","#e0aab3"],"p":70,"t":"Omarming","d":"Twee figuren in violet en roze, verzonken in een omhelzing. Zacht en liefdevol, een werk vol tederheid.","own":false,"e":"Two figures in violet and pink, lost in an embrace. Soft and loving, a work full of tenderness.","x":"Een omhelzing zegt wat woorden niet kunnen: ik ben er. Dit werk is gemaakt van die tederheid, zacht en zonder voorbehoud.","xe":"An embrace says what words cannot: I am here. This work is made of that tenderness, soft and without reservation."},{"id":"123","nr":"NV-123","thema":"figuur","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.6024,"avg":"#8f7170","pal":["#432b32","#84676e","#ab8c92","#be9e96","#d5b084"],"p":70,"t":"Oertijd","d":"Rennende figuren als in een oude grotschildering, op roze en goud. Een knipoog naar de oudste kunst ter wereld.","own":false,"e":"Running figures as in an ancient cave painting, on pink and gold. A nod to the oldest art in the world.","x":"Lang voordat er woorden waren, schilderden mensen op rotsen: rennend, jagend, dansend. Dit werk knipoogt naar die eerste kunstenaars, en herinnert eraan hoe oud het verlangen is om iets na te laten.","xe":"Long before there were words, people painted on rocks: running, hunting, dancing. This work nods to those first artists, and reminds us how old the longing is to leave something behind."},{"id":"124","nr":"NV-124","thema":"figuur","kleur":["blauw","zwart"],"ori":"vierkant","type":"enkel","ar":0.9889,"avg":"#343d50","pal":["#161b29","#3f251c","#31415d","#406084","#5389bb"],"p":71,"t":"Vrouwen","d":"Vrouwen in blauw en bruin, omringd door Afrikaanse patronen. Warm, krachtig en waardig. Rechtsonder gesigneerd.","own":false,"e":"Women in blue and brown, surrounded by African patterns. Warm, strong and dignified. Signed lower right.","x":"Er is een waardigheid die niets hoeft te bewijzen. Deze vrouwen dragen haar in houding en kleur. Een warm, krachtig werk over vrouwen die een gemeenschap dragen.","xe":"There is a dignity that needs to prove nothing. These women carry it in their bearing and their colour. A warm, powerful work about the women who hold a community together."},{"id":"125","nr":"NV-125","thema":"figuur","kleur":["groen","zwart"],"ori":"liggend","type":"enkel","ar":2.0604,"avg":"#156343","pal":["#05372c","#098356","#038952","#49a16f","#1f382c"],"p":72,"t":"Muze","d":"Een vrouwengezicht in groen met rode lippen, opvallend en verleidelijk. Een portret dat de blik vasthoudt.","own":false,"e":"A woman's face in green with red lips, striking and seductive. A portrait that holds the gaze.","x":"Iedereen heeft ooit een muze gehad, of was er een: iemand die een ander inspireert zonder het te weten. Dit portret houdt die betovering vast, opvallend en een beetje raadselachtig.","xe":"Everyone has had a muse, or been one: someone who inspires another without knowing it. This portrait holds that enchantment, striking and a little enigmatic."},{"id":"126","nr":"NV-126","thema":"figuur","kleur":["blauw","zwart"],"ori":"liggend","type":"enkel","ar":2.0604,"avg":"#314968","pal":["#051d34","#0485ab","#42577c","#50294a","#598da2"],"p":72,"t":"Portret van een Man","d":"Een mannengezicht in turquoise en roze tegen diep blauw. Karaktervol en direct, met een vrije, expressieve toets.","own":false,"e":"A man's face in turquoise and pink against deep blue. Full of character and direct, with a free, expressive touch.","x":"Een gezicht vertelt een leven, als je goed kijkt. Deze man kijkt terug, direct en zonder masker. Een portret met karakter, voor wie houdt van eerlijkheid.","xe":"A face tells a life, if you look closely. This man looks back, direct and unmasked. A portrait with character, for those who love honesty."},{"id":"127","nr":"NV-127","thema":"figuur","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":0.9572,"avg":"#9f433b","pal":["#ea0d13","#009152","#b75e50","#9b1128","#5a9466"],"p":73,"t":"Moederschap","d":"Twee vrouwen in rood met een kind op schoot, tegen frisgroen. Ontroerend en vol warmte. Een werk over zorg en verbondenheid.","own":false,"e":"Two women in red with a child on their lap, against fresh green. Moving and full of warmth. A work about care and connection.","x":"Het oudste gebaar van de wereld: een kind dat wordt vastgehouden. Dit werk is er een eerbetoon aan, aan moeders, aan grootmoeders, aan iedereen die ooit iemand heeft gedragen.","xe":"The oldest gesture in the world: a child being held. This work is a tribute to it, to mothers, to grandmothers, to everyone who has ever carried someone."},{"id":"128","nr":"NV-128","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#5e96bd","pal":["#358dbd","#2143a1","#acc7c8","#69b9cb","#c2d7d3"],"p":74,"t":"Spiegeling","d":"Bomen in blauw en turquoise spiegelen zich in het water. Fris en sereen, met de stilte van een vroege ochtend.","own":false,"e":"Trees in blue and turquoise are mirrored in the water. Fresh and serene, with the stillness of early morning.","x":"Stil water laat de wereld twee keer zien. In die spiegeling zit iets van bezinning: kijken naar wat is, en naar wat het teruggeeft. Een sereen werk voor een rustig begin van de dag.","xe":"Still water shows the world twice. In that reflection lies something of contemplation: looking at what is, and at what it gives back. A serene work for a quiet start to the day."},{"id":"129","nr":"NV-129","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#95b7b8","pal":["#60a7c7","#f0f4e8","#335f7d","#d0e0cd","#f3f5b8"],"p":74,"t":"Sneeuw","d":"Een berg in wit en geel tegen een blauwe hemel. Helder als een winterochtend in de bergen.","own":false,"e":"A mountain in white and yellow against a blue sky. As clear as a winter morning in the mountains.","x":"Verse sneeuw maakt alles nieuw. Geen sporen nog, alleen licht. Dit werk heeft die helderheid van een winterochtend in de bergen, en de rust van een wit begin.","xe":"Fresh snow makes everything new. No footprints yet, only light. This work has the clarity of a winter morning in the mountains, and the calm of a white beginning."},{"id":"130","nr":"NV-130","thema":"landschap","kleur":["blauw","zwart"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#8e937c","pal":["#ebd0c5","#141635","#c6d280","#718d7d","#ebdbb9"],"p":75,"t":"Knotwilgen","d":"Een rij donkere knotwilgen in een veld van geel en groen. Hollands landschap, teruggebracht tot zijn essentie.","own":false,"e":"A row of dark pollard willows in a field of yellow and green. Dutch landscape, reduced to its essence.","x":"Knotwilgen staan er al generaties, eigenwijs en trouw, langs sloten die niemand meer kent. Ze zijn het geduld van het Hollandse land. Een werk vol stille verbondenheid met waar we vandaan komen.","xe":"Pollard willows have stood for generations, stubborn and loyal, along ditches no one remembers. They are the patience of the Dutch land. A work full of quiet attachment to where we come from."},{"id":"131","nr":"NV-131","thema":"landschap","kleur":["geel","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#806d46","pal":["#072c40","#f3c96b","#5c2d25","#f5ab44","#a7a15b"],"p":75,"t":"Laan","d":"Een bomenrij in rood, geel en blauw onder een zonnige lucht. Kleurrijk en vrolijk, als een laan in de nazomer.","own":false,"e":"A row of trees in red, yellow and blue under a sunny sky. Colourful and cheerful, like an avenue in late summer.","x":"Een laan is een uitnodiging om te wandelen, langzaam, zonder doel. Dit werk is die nazomerse middag: kleurrijk, licht, met de belofte dat er nog tijd is.","xe":"An avenue is an invitation to walk, slowly, without purpose. This work is that late-summer afternoon: colourful, light, with the promise that there is still time."},{"id":"132","nr":"NV-132","thema":"natuur","kleur":["zwart"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#70664a","pal":["#ded175","#0f151d","#1c1c20","#9e3d4b","#718460"],"p":76,"t":"Berkenbos","d":"Witte stammen tussen roze, geel en turquoise, grafisch en fris. Een bos als patroon van licht en kleur.","own":false,"e":"White trunks among pink, yellow and turquoise, graphic and fresh. A forest as a pattern of light and colour.","x":"Een berkenbos heeft iets onwerkelijks: witte stammen die licht lijken te geven. Dit werk vangt die betovering, fris en grafisch, als een sprookje dat net begint.","xe":"A birch wood has something unreal about it: white trunks that seem to give off light. This work captures that enchantment, fresh and graphic, like a fairy tale just beginning."},{"id":"133","nr":"NV-133","thema":"natuur","kleur":["zwart","geel"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#75603f","pal":["#221b1c","#62382a","#8f714b","#b0a960","#d4cc78"],"p":76,"t":"Kern","d":"Een ronde vorm vol lijnen in bruin, geel en roze, als een vrucht van binnenuit gezien. Organisch en geheimzinnig.","own":false,"e":"A round form full of lines in brown, yellow and pink, like a fruit seen from within. Organic and mysterious.","x":"Alles wat groeit, begint in een kern. Een zaad, een idee, een gevoel. Dit werk kijkt naar binnen, naar het geheim waaruit iets ontstaat.","xe":"Everything that grows begins at a core. A seed, an idea, a feeling. This work looks inward, at the secret from which something comes into being."},{"id":"134","nr":"NV-134","thema":"natuur","kleur":["geel","blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#83a246","pal":["#279e93","#f9d801","#3b453a","#fce200","#aec84b"],"p":77,"t":"Gebladerte","d":"Gele bladvormen met rode kernen op turquoise, uitgesproken en zonnig. Een grafisch werk met de frisheid van de natuur.","own":false,"e":"Yellow leaf shapes with red centres on turquoise, outspoken and sunny. A graphic work with the freshness of nature.","x":"Bladeren in de zon geven een dag zijn stemming. Dit werk is zo'n dag: helder, zomers, vol leven dat zich naar het licht keert.","xe":"Leaves in the sun set the mood of a day. This work is such a day: bright, summery, full of life turning towards the light."},{"id":"135","nr":"NV-135","thema":"natuur","kleur":["rood"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#d31f07","pal":["#df0202","#a90203","#ef4507","#d2190a","#f17614"],"p":77,"t":"Rijping","d":"Een oranje vrucht gloeit in een zee van rood. Warm, vol en zinnelijk.","own":false,"e":"An orange fruit glows in a sea of red. Warm, full and sensuous.","x":"Rijpheid is geduld dat zoet wordt. Wat de tijd kreeg, krijgt smaak. Dit werk gloeit met die volheid, warm en zinnelijk.","xe":"Ripeness is patience turned sweet. What was given time gains flavour. This work glows with that fullness, warm and sensual."},{"id":"136","nr":"NV-136","thema":"natuur","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":1.0,"avg":"#a92e2e","pal":["#ec030a","#7a070e","#c2b2a5","#9c665d","#92201f"],"p":78,"t":"The Big Apple","d":"Een grote rode appel waarin de woorden New York en Big Apple zijn geschilderd. Een speelse ode aan de stad, en een van de iconische werken uit de collectie.","own":true,"e":"A large red apple with the words New York and Big Apple painted into it. A playful tribute to the city, and one of the iconic works in the collection.","x":"New York noemt zichzelf de grote appel: iets om in te bijten, groot, verleidelijk, vol leven. Nanny maakte er met een glimlach letterlijk een appel van. Een iconisch werk, voor wie de stad in het hart draagt.","xe":"New York calls itself the Big Apple: something to bite into, big, tempting, full of life. Nanny, with a smile, made it literally an apple. An iconic work, for those who carry the city in their heart."},{"id":"137","nr":"NV-137","thema":"natuur","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":1.0,"avg":"#811016","pal":["#b20103","#680202","#6b070a","#915365","#711823"],"p":79,"t":"Rozen","d":"Dieprode bloemvormen met accenten van roze en blauw. Romantisch en intens, in rijke lagen verf.","own":false,"e":"Deep red flower forms with accents of pink and blue. Romantic and intense, in rich layers of paint.","x":"Rozen zijn de oudste taal van de liefde. Dit werk spreekt haar in diep rood, rijk en intens. Een geschenk dat blijft bloeien.","xe":"Roses are the oldest language of love. This work speaks it in deep red, rich and intense. A gift that keeps on blooming."},{"id":"138","nr":"NV-138","thema":"natuur","kleur":["rood"],"ori":"vierkant","type":"enkel","ar":1.0,"avg":"#7b1b2d","pal":["#61050c","#71101d","#ac0310","#85233c","#5b82b7"],"p":79,"t":"Tulp","d":"Een grote rode bloem tegen een strook helder blauw. Krachtig, elegant en met grote zelfverzekerdheid geschilderd.","own":false,"e":"A large red flower against a strip of bright blue. Strong, elegant and painted with great confidence.","x":"Eén bloem, met volle overtuiging geschilderd. Er zit Hollandse trots in, en zelfvertrouwen. Een werk dat laat zien hoe mooi het is om helemaal jezelf te zijn.","xe":"One flower, painted with full conviction. There is Dutch pride in it, and self-confidence. A work that shows how beautiful it is to be entirely yourself."},{"id":"139","nr":"NV-139","thema":"natuur","kleur":["blauw","geel"],"ori":"liggend","type":"enkel","ar":1.5924,"avg":"#997b49","pal":["#064499","#fca604","#fcc90a","#c14e26","#9aa369"],"p":80,"t":"Goudsbloemen","d":"Oranje en gele bloemen op diep blauw, zon en zomer in één beeld. Stralend en warm.","own":false,"e":"Orange and yellow flowers on deep blue, sun and summer in one image. Radiant and warm.","x":"Goudsbloemen bloeien tot laat in het jaar, alsof ze de zomer niet willen laten gaan. Dit werk heeft die trouwe warmte: zon die blijft schijnen, ook als de dagen korter worden.","xe":"Marigolds bloom late into the year, as if they do not want to let summer go. This work has that faithful warmth: sun that keeps shining, even as the days grow shorter."},{"id":"140","nr":"NV-140","thema":"natuur","kleur":["rood"],"ori":"liggend","type":"enkel","ar":2.7383,"avg":"#9f1e25","pal":["#f40201","#76181c","#7579a1","#983833","#8f060b"],"p":80,"t":"Klaprozen","d":"Rode klaprozen tegen donkerblauw. Een smal, levendig werk, mooi boven een dressoir.","own":false,"e":"Red poppies against dark blue. A narrow, lively work, lovely above a sideboard.","x":"Klaprozen staan voor herinnering: fragiel, rood, ieder jaar terug. Dit kleine werk draagt die betekenis met lichtheid, levendig en ontroerend tegelijk.","xe":"Poppies stand for remembrance: fragile, red, returning every year. This small work carries that meaning lightly, lively and moving at once."},{"id":"141","nr":"NV-141","thema":"natuur","kleur":["rood","blauw"],"ori":"vierkant","type":"tweeluik","ar":0.9956,"avg":"#9f3033","pal":["#3c255c","#ef0001","#f90100","#bb0103","#91996e"],"p":81,"t":"Hot Spring","d":"Een tweeluik in rood, geel en blauw dat opborrelt van energie. Nanny's titel roept een warme bron op: kleur die naar boven komt.","own":true,"e":"A diptych in red, yellow and blue that bubbles with energy. Nanny's title evokes a hot spring: colour welling up.","x":"Warmte die van binnenuit komt, laat zich niet tegenhouden. Kleur borrelt op, energie wil naar boven, zoals vreugde die je niet voor jezelf kunt houden. Een werk dat een ruimte direct tot leven brengt.","xe":"Warmth that comes from within cannot be held back. Colour bubbles up, energy rises, like a joy you cannot keep to yourself. A work that brings a space to life at once.","gaps":[[48.023,52.103]]},{"id":"142","nr":"NV-142","thema":"natuur","kleur":["geel","blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#978b62","pal":["#322b58","#f9c52e","#cac883","#676a6f","#f9dd54"],"p":82,"t":"Zonnewende","d":"Een tweeluik met goud en geel tussen nachtblauw. Stralend en warm, als het licht op de langste dag.","own":false,"e":"A diptych of gold and yellow between midnight blue. Radiant and warm, like the light on the longest day.","x":"Op de langste dag blijft het licht tot diep in de avond. Er zit iets feestelijks in, en iets kostbaars. Dit tweeluik viert dat moment, stralend tussen twee nachten.","xe":"On the longest day, the light lingers deep into the evening. There is something festive in it, and something precious. This diptych celebrates that moment, radiant between two nights.","gaps":[[48.047,52.139]]},{"id":"143","nr":"NV-143","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"tweeluik","ar":1.0374,"avg":"#8c2224","pal":["#501220","#d40114","#ee0102","#707460","#900208"],"p":83,"t":"Golfslag","d":"Een tweeluik waarin rood als een golf over groen en zwart rolt. Krachtig en meeslepend.","own":false,"e":"A diptych in which red rolls like a wave over green and black. Powerful and compelling.","x":"Sommige gevoelens komen als een golf: je kunt ze niet tegenhouden, alleen erop meebewegen. Dit tweeluik heeft die meeslepende kracht, rood en vol overgave.","xe":"Some feelings come like a wave: you cannot stop them, only move with them. This diptych has that sweeping force, red and full of surrender.","gaps":[[48.012,52.112]]},{"id":"144","nr":"NV-144","thema":"natuur","kleur":["blauw","rood"],"ori":"vierkant","type":"enkel","ar":0.998,"avg":"#ac6e60","pal":["#5cb1d1","#fa0101","#e3be61","#fa2e06","#72334e"],"p":84,"t":"De Verwelkte Roos","d":"Rode bloembladen vallen uiteen over geel en blauw. Nanny's titel maakt er een werk van over schoonheid en vergankelijkheid.","own":true,"e":"Red petals fall apart over yellow and blue. Nanny's title makes it a work about beauty and transience.","x":"Een verwelkte roos is nog steeds een roos. Misschien zelfs mooier, omdat ze laat zien dat schoonheid tijd heeft gekend. Een stille overpeinzing over ouder worden, en over wat dan blijft.","xe":"A wilted rose is still a rose. Perhaps even more beautiful, because it shows that beauty has known time. A quiet meditation on growing older, and on what remains."},{"id":"145","nr":"NV-145","thema":"abstract","kleur":["blauw"],"ori":"vierkant","type":"tweeluik","ar":0.9194,"avg":"#7d7761","pal":["#225087","#b6412c","#6e8e7c","#d2c65f","#89b24c"],"p":85,"t":"Kinderdroom","d":"Een tweeluik vol figuurtjes, raketten en vruchten in felle kleuren. Speels en vrolijk, met de vrijheid van een kindertekening.","own":false,"e":"A diptych full of little figures, rockets and fruit in bright colours. Playful and joyful, with the freedom of a child's drawing.","x":"Kinderen tekenen zonder te twijfelen: raketten, fruit, poppetjes, alles mag. Dit werk heeft die onbevangen vreugde. Voor een huis waar gespeeld wordt, of voor wie het spelen niet wil verleren.","xe":"Children draw without hesitation: rockets, fruit, little figures, anything goes. This work has that unselfconscious joy. For a home where there is play, or for anyone who does not want to forget how to play.","gaps":[[48.063,52.141]]},{"id":"146","nr":"NV-146","thema":"natuur","kleur":["blauw","zwart"],"ori":"staand","type":"enkel","ar":0.7682,"avg":"#1e507d","pal":["#5aa9da","#0d6ab7","#080c1e","#0a1737","#0b2855"],"p":86,"t":"De Kracht","d":"Een olifant van voren, donkerblauw tegen hemelsblauw. Majestueus en rustig, met een onverstoorbare aanwezigheid.","own":true,"e":"An elephant seen from the front, dark blue against sky blue. Majestic and calm, with an imperturbable presence.","x":"Echte kracht hoeft niet te brullen. Ze staat stil en is er gewoon. Nanny noemde deze olifant De Kracht, en je voelt het: een onverstoorbare aanwezigheid die rust geeft.","xe":"True strength need not roar. It stands still and simply is. Nanny named this elephant The Strength, and you feel it: an imperturbable presence that gives calm."},{"id":"147","nr":"NV-147","thema":"natuur","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.3547,"avg":"#923e2d","pal":["#620302","#890202","#c5a271","#90452b","#d6be9c"],"p":86,"t":"Vogelvlucht","d":"Twee vogels in crème en oranje op dieprood. Vrij en licht, alsof ze elk moment kunnen opvliegen.","own":true,"e":"Two birds in cream and orange on deep red. Free and light, as if they might take flight at any moment.","x":"Twee vogels op het punt van opvliegen: het moment net voor de vrijheid. Er zit belofte in, en lichtheid. Een werk voor wie klaar is om iets los te laten.","xe":"Two birds on the point of taking flight: the moment just before freedom. There is promise in it, and lightness. A work for anyone ready to let something go."},{"id":"148","nr":"NV-148","thema":"natuur","kleur":["zwart"],"ori":"staand","type":"enkel","ar":0.7682,"avg":"#433d3c","pal":["#0c0805","#595151","#867e7e","#130f0e","#2a2625"],"p":86,"t":"The Black Elephant","d":"Een olifant in grijs en wit op diep zwart. Indrukwekkend en sereen, met een prachtige textuur.","own":true,"e":"An elephant in grey and white on deep black. Impressive and serene, with beautiful texture.","x":"Olifanten vergeten nooit, zegt men. Dit dier lijkt alles te dragen wat het heeft gezien, met een ernst die ontroert. Een indrukwekkend, sereen werk over wijsheid en herinnering.","xe":"Elephants never forget, they say. This animal seems to carry everything it has seen, with a gravity that moves you. An impressive, serene work about wisdom and memory."},{"id":"149","nr":"NV-149","thema":"natuur","kleur":["blauw","zwart"],"ori":"liggend","type":"enkel","ar":1.3547,"avg":"#2b3c4f","pal":["#26445f","#6d737b","#071829","#021c38","#24222d"],"p":86,"t":"Meneer de Uil","d":"Een uil in bruin en oker kijkt je aan vanuit het nachtblauw. Wijs en innemend, met een vleugje humor in Nanny's eigen titel.","own":true,"e":"An owl in brown and ochre looks at you from the midnight blue. Wise and endearing, with a touch of humour in Nanny's own title.","x":"Een uil ziet wat anderen in het donker missen. Deze kijkt u aan met de rust van iemand die alles al eens heeft meegemaakt. Wijs, innemend, en een beetje een vriend aan de muur.","xe":"An owl sees what others miss in the dark. This one looks at you with the calm of someone who has seen it all before. Wise, endearing, and a little like a friend on the wall."},{"id":"150","nr":"NV-150","thema":"natuur","kleur":["blauw","zwart"],"ori":"vierkant","type":"enkel","ar":0.9815,"avg":"#555b64","pal":["#949ba0","#5d6671","#202029","#4a505d","#3b4353"],"p":87,"t":"Tederheid","d":"Twee olifanten in grijs en wit, met slurven die elkaar bijna raken. Monumentaal en tegelijk ontroerend teder.","own":false,"e":"Two elephants in grey and white, trunks almost touching. Monumental and at the same time movingly tender.","x":"Twee reuzen die elkaar bijna aanraken, met een zachtheid die je niet verwacht. Dit werk laat zien dat tederheid geen kwestie van grootte is. Een ontroerend beeld van genegenheid.","xe":"Two giants almost touching, with a gentleness you would not expect. This work shows that tenderness is not a matter of size. A moving image of affection."},{"id":"151","nr":"NV-151","thema":"abstract","kleur":["rood"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#7c1723","pal":["#9a0403","#7f4160","#620407","#a90403","#6f1423"],"p":88,"t":"Herinnering","d":"Een tweeluik in rood en violet waarin vormen als gezichten opdoemen en weer verdwijnen. Gelaagd en intens.","own":false,"e":"A diptych in red and violet in which forms like faces emerge and fade again. Layered and intense.","x":"Herinneringen komen en gaan zoals gezichten in een droom: even helder, dan weer weg. Dit tweeluik geeft dat proces kleur. Intens en gelaagd, als het geheugen zelf.","xe":"Memories come and go like faces in a dream: clear for a moment, then gone. This diptych gives that process colour. Intense and layered, like memory itself.","gaps":[[48.047,52.139]]},{"id":"152","nr":"NV-152","thema":"natuur","kleur":["oranje"],"ori":"vierkant","type":"tweeluik","ar":1.0398,"avg":"#604c35","pal":["#122423","#ce8038","#6c321b","#715737","#568789"],"p":89,"t":"Reigers","d":"Een tweeluik met reigerachtige silhouetten in groen tegen oranje en violet. Grafisch, stil en elegant.","own":false,"e":"A diptych of heron-like silhouettes in green against orange and violet. Graphic, still and elegant.","x":"Een reiger kan eindeloos stilstaan, wachtend op het juiste moment. Er zit een les in dat geduld. Dit tweeluik heeft die elegante stilte.","xe":"A heron can stand still endlessly, waiting for the right moment. There is a lesson in that patience. This diptych has that elegant stillness.","gaps":[[47.931,52.069]]},{"id":"153","nr":"NV-153","thema":"landschap","kleur":["zwart","blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#223635","pal":["#181413","#263533","#2e7071","#23201c","#1a1e1f"],"p":90,"t":"Nachtzee","d":"Teal en zwart met een gouden gloed, als de zee bij nacht. Stil en geheimzinnig.","own":false,"e":"Teal and black with a golden glow, like the sea at night. Quiet and mysterious.","x":"'s Nachts wordt de zee geheimzinnig: alleen geluid, beweging en hier en daar een glans. Dit werk vangt dat mysterie en geeft een kamer de diepte van open water.","xe":"At night the sea becomes mysterious: only sound, movement and here and there a gleam. This work captures that mystery and gives a room the depth of open water."},{"id":"154","nr":"NV-154","thema":"landschap","kleur":["rood","oranje"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#f4813f","pal":["#f55a20","#e63014","#fa9652","#feef80","#fcd76d"],"p":90,"t":"De Vuurzee","d":"Rood, oranje en geel laaien op. Nanny's titel zegt het: een zee van vuur en licht, die een ruimte onmiddellijk warmte geeft.","own":true,"e":"Red, orange and yellow blaze up. Nanny's title says it: a sea of fire and light that gives a room instant warmth.","x":"Vuur is gevaar én warmte, vernietiging én begin. Wie dit werk in huis haalt, haalt die oerkracht binnen: een doek dat de kamer verwarmt en de verbeelding ontsteekt.","xe":"Fire is danger and warmth, destruction and beginning. Whoever brings this work home brings in that primal force: a canvas that warms the room and kindles the imagination."},{"id":"155","nr":"NV-155","thema":"natuur","kleur":["blauw","zwart"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#43526f","pal":["#141625","#1d2b4d","#345486","#ced1d7","#798faa"],"p":91,"t":"Zebra","d":"Zwart, wit en blauw in krachtige strepen, waaruit dieren opduiken. Dynamisch en grafisch.","own":false,"e":"Black, white and blue in bold stripes, from which animals emerge. Dynamic and graphic.","x":"Geen zebra heeft dezelfde strepen; elk dier is uniek. In dit werk duiken ze op uit een ritme van zwart en wit. Krachtig, grafisch, en vol leven dat zich niet laat vangen.","xe":"No two zebras have the same stripes; every animal is unique. In this work they emerge from a rhythm of black and white. Powerful, graphic, and full of life that will not be caught."},{"id":"156","nr":"NV-156","thema":"abstract","kleur":["rood","blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#85707b","pal":["#192032","#9a95a6","#90383f","#c2c6d0","#dedcdc"],"p":91,"t":"Scheur","d":"Rood, wit en zwart in gescheurde vormen. Stoer en eigentijds, met de spanning van een collage.","own":false,"e":"Red, white and black in torn forms. Bold and contemporary, with the tension of a collage.","x":"Wat gescheurd is, kan opnieuw iets worden. Een collage leert dat: scherven en randen vormen samen een nieuw beeld. Een stoer werk over herstel en herschikking.","xe":"What is torn can become something again. A collage teaches this: shreds and edges together form a new image. A bold work about repair and reinvention."},{"id":"157","nr":"NV-157","thema":"stad","kleur":["blauw"],"ori":"staand","type":"enkel","ar":0.8119,"avg":"#4381b0","pal":["#3ba4d8","#11346e","#2e75ab","#97c7e4","#8ca8ba"],"p":92,"t":"Marathon Rotterdam","d":"De Erasmusbrug van onderaf, met de lopers van de marathon eronder. Rotterdam op zijn mooist, door Nanny zelf zo getiteld.","own":true,"e":"The Erasmus Bridge seen from below, with marathon runners beneath it. Rotterdam at its finest, titled by Nanny herself.","x":"Duizenden mensen, één brug, één doel: doorgaan tot de finish. Nanny schilderde de marathon van Rotterdam, de stad die haar dierbaar was. Een werk over volharding, gemeenschap en de trots van een stad.","xe":"Thousands of people, one bridge, one goal: keep going to the finish. Nanny painted the Rotterdam marathon, in a city she held dear. A work about perseverance, community and a city's pride."},{"id":"158","nr":"NV-158","thema":"stad","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#4696d4","pal":["#128ad8","#4faee0","#0c52b1","#91c3e3","#b9d6e8"],"p":93,"t":"Erasmusbridge","d":"Nanny schilderde de Erasmusbrug met grote genegenheid voor Rotterdam. Voor haar was de brug geen staal en kabels, maar een verhaal van verbinding, beweging en de ziel van de stad. In zacht blauw en lavendel vangt ze de sierlijke boog en het leven dat eronder doorstroomt: herinnering en beweging in één gebaar. Een werk dat haar liefde voor architectuur weerspiegelt, en voor plekken die mensen samenbrengen.","own":true,"e":"Nanny painted the Erasmus Bridge with deep affection for Rotterdam. To her the bridge was not steel and cables, but a story of connection, movement and the soul of the city. In soft blues and lavenders she captures its graceful arc and the life flowing beneath it: memory and motion in a single gesture. A work that reflects her love of architecture, and of places that bring people together.","x":"Bruggen verbinden wat anders gescheiden blijft: oevers, wijken, mensen. Nanny's liefde voor Rotterdam spreekt uit elke streek. Een werk voor wie weet hoeveel een plek kan betekenen.","xe":"Bridges connect what would otherwise remain apart: banks, neighbourhoods, people. Nanny's love for Rotterdam speaks from every stroke. A work for anyone who knows how much a place can mean."},{"id":"159","nr":"NV-159","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#6094a1","pal":["#0e54b4","#62b5dc","#f2aa0c","#358ab3","#c5ce7d"],"p":93,"t":"Kustlijn","d":"Golven in blauw met stranden van geel. Zomer aan zee, teruggebracht tot kleur en lijn.","own":false,"e":"Waves in blue with beaches of yellow. Summer by the sea, reduced to colour and line.","x":"Er is een lijn waar de zee het land raakt, en daar is altijd ruimte. Dit werk brengt die horizon naar binnen. Zomer, zout, en de vrijheid van een lange wandeling langs het water.","xe":"There is a line where the sea meets the land, and there is always space there. This work brings that horizon indoors. Summer, salt, and the freedom of a long walk by the water."},{"id":"160","nr":"NV-160","thema":"stad","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.5516,"avg":"#617f84","pal":["#447080","#669eb8","#233338","#c4c8af","#a9aa93"],"p":94,"t":"Haven","d":"Kranen en lijnen boven een kade in geel en blauw, een haven in volle bedrijvigheid. Grafisch en stedelijk.","own":false,"e":"Cranes and lines above a quay in yellow and blue, a harbour at full stretch. Graphic and urban.","x":"Een haven is een plek van komen en gaan, van werk en verlangen. Kranen die laden, schepen die vertrekken naar verre plekken. Dit werk ademt die bedrijvigheid, en die belofte.","xe":"A harbour is a place of coming and going, of work and longing. Cranes loading, ships leaving for distant places. This work breathes that bustle, and that promise."},{"id":"161","nr":"NV-161","thema":"stad","kleur":["zwart"],"ori":"liggend","type":"enkel","ar":1.5491,"avg":"#7f7f7d","pal":["#cacac1","#8f9291","#423d40","#565a5f","#6f6a68"],"p":94,"t":"Kade","d":"Een kade met witte gebouwen onder een donkere hemel. Stil en sfeervol, als het moment voordat het gaat regenen.","own":false,"e":"A quay with white buildings beneath a dark sky. Quiet and atmospheric, like the moment before rain.","x":"Het moment voordat het gaat regenen heeft een eigen stilte: de lucht houdt haar adem in, de kade wacht. Dit werk vangt die spanning, stil en sfeervol.","xe":"The moment before it rains has its own silence: the sky holds its breath, the quay waits. This work captures that tension, still and atmospheric."},{"id":"162","nr":"NV-162","thema":"stad","kleur":["blauw"],"ori":"vierkant","type":"enkel","ar":1.0038,"avg":"#5c80a9","pal":["#aec5de","#79a4d0","#12284f","#2069b7","#50739c"],"p":95,"t":"Collage in Blauw","d":"Gebouwen in blauw, wit en zwart, gestapeld als een collage. Stoer en stedelijk, met veel textuur.","own":false,"e":"Buildings in blue, white and black, stacked like a collage. Bold and urban, with rich texture.","x":"Een stad wordt gebouwd in lagen: oud over nieuw, herinnering over haast. Dit werk stapelt die lagen in blauw. Stoer en gelaagd, als het stadsleven zelf.","xe":"A city is built in layers: old over new, memory over hurry. This work stacks those layers in blue. Bold and layered, like city life itself."},{"id":"163","nr":"NV-163","thema":"stad","kleur":["zwart"],"ori":"vierkant","type":"enkel","ar":1.0,"avg":"#66686a","pal":["#ccdbe4","#15100d","#2f2c2b","#1d1715","#8d9296"],"p":95,"t":"De Fabriek","d":"Een fabriek in wit op diep zwart, getekend als een blauwdruk. Industrieel en sterk, door Nanny zelf zo getiteld.","own":true,"e":"A factory in white on deep black, drawn like a blueprint. Industrial and strong, titled by Nanny herself.","x":"Fabrieken waren ooit het hart van een stad: werk, brood, trots. Nanny tekende er een als een blauwdruk, met eerbied voor wat mensen hebben gebouwd. Een industrieel werk met ziel.","xe":"Factories were once the heart of a city: work, bread, pride. Nanny drew one like a blueprint, with reverence for what people have built. An industrial work with a soul."},{"id":"164","nr":"NV-164","thema":"stad","kleur":["blauw","zwart"],"ori":"vierkant","type":"enkel","ar":1.0038,"avg":"#142f4a","pal":["#140a0b","#123b61","#0f243b","#194d78","#235c88"],"p":95,"t":"Ship by Night","d":"Een schip aan de kade in nachtblauw en rood. Stil en vol sfeer, met de rust van de haven na sluitingstijd.","own":true,"e":"A ship at the quay in midnight blue and red. Quiet and atmospheric, with the calm of the harbour after hours.","x":"Als de haven stilvalt en het schip aan de kade ligt, begint een andere rust. Nanny noemde het Ship by Night. Een werk vol de vrede van een dag die voorbij is.","xe":"When the harbour falls silent and the ship lies at the quay, a different calm begins. Nanny named it Ship by Night. A work full of the peace of a day that is done."},{"id":"165","nr":"NV-165","thema":"landschap","kleur":["blauw","zwart"],"ori":"vierkant","type":"enkel","ar":1.0,"avg":"#5e6c6d","pal":["#9bacaa","#6e8589","#232a31","#5f5d4e","#3c4e54"],"p":95,"t":"De Ondergang","d":"Een schip kapseist in een woeste zee. Dramatisch en meeslepend, een van haar meest verhalende werken.","own":true,"e":"A ship capsizes in a raging sea. Dramatic and compelling, one of her most narrative works.","x":"Niet elk verhaal loopt goed af, en ook die verhalen verdienen een plek. Nanny schilderde De Ondergang met drama en eerbied. Een werk over de kracht van de natuur, en over wat we niet in de hand hebben.","xe":"Not every story ends well, and those stories deserve a place too. Nanny painted The Sinking with drama and reverence. A work about the power of nature, and about what we cannot control."},{"id":"166","nr":"NV-166","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6754,"avg":"#a0acb8","pal":["#a5bed3","#97aebf","#897a7b","#b7c2cf","#bfcdd8"],"p":96,"t":"Haven met Zeilen","d":"Masten en boten in wit, blauw en rood, een zonnige haven vol zeilen. Licht en zomers.","own":false,"e":"Masts and boats in white, blue and red, a sunny harbour full of sails. Light and summery.","x":"Een haven vol zeilen is een zomerdag vol mogelijkheden. Waar ga je heen? Het maakt niet uit. Dit werk heeft die zonnige vrijheid.","xe":"A harbour full of sails is a summer's day full of possibility. Where will you go? It does not matter. This work has that sunny freedom."},{"id":"167","nr":"NV-167","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6816,"avg":"#5397c3","pal":["#d0dad6","#037ece","#58adc3","#0c52b7","#2e84ae"],"p":96,"t":"Regatta","d":"Witte zeilen op diepblauw water. Snelheid, wind en vrijheid, gevangen in een paar zekere streken.","own":false,"e":"White sails on deep blue water. Speed, wind and freedom, captured in a few assured strokes.","x":"Wind in de zeilen, het water dat langs de boeg ruist: weinig dingen voelen zo vrij. Dit werk vangt die vaart in een paar zekere streken.","xe":"Wind in the sails, water rushing past the bow: few things feel so free. This work captures that speed in a few assured strokes."},{"id":"168","nr":"NV-168","thema":"landschap","kleur":["blauw","oranje"],"ori":"liggend","type":"enkel","ar":1.6779,"avg":"#b8bfc3","pal":["#bdbdbc","#c4d5da","#7a8ea2","#e2d2c7","#e5e3e0"],"p":97,"t":"Zeilen","d":"Zeilen in zalm en blauw, losjes en licht geschilderd. Een werk met de lichtheid van een zomerdag op het water.","own":false,"e":"Sails in salmon and blue, painted loosely and lightly. A work with the lightness of a summer day on the water.","x":"Sommige dagen op het water vergeet je nooit, ook al gebeurde er niets bijzonders. Dit werk is zo'n dag: licht, zacht, vol zon.","xe":"Some days on the water you never forget, even though nothing special happened. This work is such a day: light, soft, full of sun."},{"id":"169","nr":"NV-169","thema":"landschap","kleur":["blauw"],"ori":"liggend","type":"enkel","ar":1.6779,"avg":"#aab2ae","pal":["#9bb1ad","#6e675f","#c1d2d1","#e2e3e0","#dedbd6"],"p":97,"t":"Wrakhout","d":"Lijnen en vlekken in zwart, oranje en teal op wit. Ruig en poëtisch, als wat de zee achterlaat.","own":false,"e":"Lines and patches in black, orange and teal on white. Rugged and poetic, like what the sea leaves behind.","x":"Wat de zee teruggeeft, heeft een reis achter de rug. Gebleekt, verweerd, en juist daardoor mooi. Dit werk heeft die ruige poëzie van wat overblijft na de storm.","xe":"What the sea gives back has made a journey. Bleached, weathered, and beautiful because of it. This work has the rugged poetry of what remains after the storm."},{"id":"170","nr":"NV-170","thema":"figuur","kleur":["rood"],"ori":"vierkant","type":"tweeluik","ar":1.0373,"avg":"#bc4f48","pal":["#e70905","#a36367","#900b15","#bfb8a7","#ebd09e"],"p":98,"t":"Markt","d":"Een tweeluik met een markt onder rode luifels, vol fruit, mensen en kleur. Levendig en warm, als een ochtend in het zuiden.","own":false,"e":"A diptych of a market under red awnings, full of fruit, people and colour. Lively and warm, like a morning in the south.","x":"Een markt in het zuiden is een feest voor alle zintuigen: kleur, geur, stemmen, zon. Dit tweeluik brengt die ochtend thuis, warm en vol leven.","xe":"A market in the south is a feast for every sense: colour, scent, voices, sun. This diptych brings that morning home, warm and full of life.","gaps":[[48.047,52.139]]},{"id":"171","nr":"NV-171","thema":"abstract","kleur":["blauw"],"ori":"vierkant","type":"tweeluik","ar":1.0398,"avg":"#4e6179","pal":["#368cbc","#072156","#7a3d24","#86acc9","#7b8994"],"p":99,"t":"Tussen Wal en Schip","d":"Een tweeluik met emmers en een zeil in blauw en oranje. Nanny's eigen titel, een Nederlandse uitdrukking, geeft het werk een tweede laag.","own":true,"e":"A diptych with buckets and a sail in blue and orange. Nanny's own title, a Dutch expression for falling between two stools, gives the work a second layer.","x":"Tussen wal en schip vallen overkomt iedereen weleens: even nergens bij horen, tussen twee plekken, twee fases, twee levens in. Dit werk kijkt er met een glimlach en met begrip naar, en laat zien dat je ook daar je weg vindt.","xe":"Falling between quay and ship, as the Dutch saying goes, happens to everyone at some point: briefly belonging nowhere, between two places, two stages, two lives. This work looks at it with a smile and with understanding, and shows that you find your way there too.","gaps":[[47.931,52.069]]}];

/* ---------- taal ---------- */
let lang = "nl";
try { const s = localStorage.getItem("nv-lang"); if (s === "en" || s === "nl") lang = s; } catch (e) {}
const L = (nl, en) => lang === "en" ? en : nl;

/* ---------- basis ---------- */
const THEMES = { abstract:["Abstract","Abstract"], landschap:["Landschap & water","Landscape & water"], stad:["Stad & architectuur","City & architecture"], figuur:["Figuur & portret","Figure & portrait"], natuur:["Natuur & dier","Nature & animals"] };
const thName = k => L(THEMES[k][0], THEMES[k][1]);
const COLORS = { rood:["Rood","Red","#C3241D"], warm:["Oranje & geel","Orange & yellow","#EBA61C"], blauw:["Blauw","Blue","#1E4CA0"], groen:["Groen","Green","#2D7F55"], paars:["Roze & paars","Pink & purple","#A84C93"], zwart:["Donker","Dark","#262624"] };
const ORI = { liggend:["Liggend","Landscape"], staand:["Staand","Portrait"], vierkant:["Vierkant","Square"] };
const HIGHLIGHTS = ["136","150","112","157","071","080","167","010","114","069"];
const THEME_COVER = { abstract:"069", landschap:"167", stad:"157", figuur:"112", natuur:"149" };
const ckey = f => (f==="oranje"||f==="geel") ? "warm" : f;
function hueOf(hex){const r=parseInt(hex.slice(1,3),16)/255,g=parseInt(hex.slice(3,5),16)/255,b=parseInt(hex.slice(5,7),16)/255;const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;let h=0;if(d<.06)return 400+(1-mx)*100;if(mx===r)h=((g-b)/d)%6;else if(mx===g)h=(b-r)/d+2;else h=(r-g)/d+4;return (h*60+360)%360;}
WORKS.forEach(w => { w.ck=[...new Set(w.kleur.map(ckey))]; w.hue=hueOf(w.avg); });
const byId = Object.fromEntries(WORKS.map(w=>[w.id,w]));
const M = id => META[id] || {};
const title = id => M(id).titel || (byId[id]&&byId[id].t) || "—";
const desc = w => L(w.d, w.e);
const status = id => M(id).status || "beschikbaar";
const fmtEUR = n => "€ " + Number(n).toLocaleString("nl-NL");
const dimText = id => { const m=M(id); if(!m.w||!m.h) return null; return m.panelen ? `${m.panelen} × ${m.w} × ${m.h} cm` : `${m.w} × ${m.h} cm`; };
const IMGV = "20261113a", T = id => `img/t/NV-${id}.jpg?v=${IMGV}`, LG = id => `img/l/NV-${id}.jpg?v=${IMGV}`;
const GAP = Object.fromEntries(WORKS.filter(w=>w.gaps).map(w=>[w.id,w.gaps]));
function dipMask(img){ const m=(img.getAttribute("src")||"").match(/NV-(\d{3})\.jpg/); const g=m&&GAP[m[1]];
  const v=g?`linear-gradient(to right,${g.map(([a,b],i)=>`#000 ${i?g[i-1][1]:0}%,#000 ${a}%,transparent ${a}%,transparent ${b}%`).join(",")},#000 ${g[g.length-1][1]}%,#000 100%)`:"";
  img.style.webkitMaskImage=v; img.style.maskImage=v; if(g){ img.style.boxShadow="none"; img.style.background="transparent"; const p=img.parentElement; if(p&&p.classList.contains("ph")) p.style.background="transparent"; } }
new MutationObserver(ms=>{ for(const m of ms){ if(m.type==="attributes"){ if(m.target.tagName==="IMG") dipMask(m.target); continue; } m.addedNodes.forEach(n=>{ if(n.nodeType!==1) return; if(n.tagName==="IMG") dipMask(n); n.querySelectorAll&&n.querySelectorAll("img").forEach(dipMask); }); } }).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:["src"]});
const esc = s => String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const wa = txt => SITE.contact.whatsapp ? `https://wa.me/${SITE.contact.whatsapp}?text=${encodeURIComponent(txt)}` : null;
const firstName = SITE.contact.naam.split(" ")[0];
const mailLink = (subj) => SITE.contact.email ? `<a href="mailto:${SITE.contact.email}${subj?`?subject=${encodeURIComponent(subj)}`:""}" class="sel">${esc(SITE.contact.email)}</a>` : "";
const initials = SITE.contact.naam.split(" ").map(p=>p[0]).join("").slice(0,2);

/* ---------- toestand ---------- */
const S = { q:"", find:{step:0,ruimte:null,sfeer:null,kleur:null}, f:{thema:null,kleur:null,ori:null,tweeluik:false}, sort:"catalogus", list:WORKS.map(w=>w.id), scroll:{}, inquiry:{works:[],type:"buy"}, filtersOpen:false };
let saved=[];
try { saved = JSON.parse(localStorage.getItem("nv-saved")||"[]").filter(id=>byId[id]); } catch(e) { saved=[]; }
const persist = () => { try { localStorage.setItem("nv-saved", JSON.stringify(saved)); } catch(e) {} };
function toggleSave(id){ const i=saved.indexOf(id); if(i>-1){saved.splice(i,1); toast(L("Verwijderd uit uw selectie","Removed from your selection"));} else {saved.push(id); toast(L(`${title(id)} bewaard`,`${title(id)} saved`));} persist(); syncSaved(); }
function syncSaved(){ document.querySelectorAll(".savedCount").forEach(e=>e.textContent=saved.length); document.querySelectorAll("[data-save]").forEach(b=>b.setAttribute("aria-pressed", saved.includes(b.dataset.save))); document.querySelectorAll("[data-save-label]").forEach(b=>b.textContent = saved.includes(b.dataset.saveLabel) ? L("Bewaard","Saved") : L("Bewaar dit werk","Save this work")); }
let tt; function toast(m){const t=document.getElementById("toast");t.textContent=m;t.classList.add("on");clearTimeout(tt);tt=setTimeout(()=>t.classList.remove("on"),2200);}
const ICON_SAVE = `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 1.5h9v13L8 11.2 3.5 14.5z" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/></svg>`;
const ICON_WA = `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 1.5a6.5 6.5 0 0 0-5.6 9.8L1.5 14.5l3.3-.9A6.5 6.5 0 1 0 8 1.5z" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg>`;
const ICON_ZOOM = `<svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><circle cx="6" cy="6" r="4.5" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M9.5 9.5 13 13M6 4v4M4 6h4" stroke="currentColor" stroke-width="1.2"/></svg>`;
const statusLine = id => status(id)==="verkocht" ? `<span class="dot"></span> ${L("Verkocht","Sold")}` : status(id)==="gereserveerd" ? `<span class="dot hollow"></span> ${L("Gereserveerd","Reserved")}` : (M(id).prijs ? fmtEUR(M(id).prijs) : (dimText(id) || L("Op aanvraag","On request")));

