function renderPicked(){
  const el=document.getElementById("picked"); if(!el) return;
  const ws=S.inquiry.works;
  el.innerHTML = ws.length ? ws.map(id=>`<figure><img src="${T(id)}" alt=""><span><span class="it">${esc(title(id))}</span><br><span class="num" style="font-size:12px;color:var(--ink-2)">Cat. ${id}</span></span><button type="button" data-unpick="${id}" aria-label="${L("Verwijder","Remove")} ${esc(title(id))}">×</button></figure>`).join("") : `<span class="muted" style="font-size:14px">${L("Geen werk gekozen.","No work selected.")} <a href="#collectie">${L("Kies in de collectie","Choose from the collection")}</a> ${L("of beschrijf in uw bericht wat u zoekt.","or describe in your message what you are looking for.")}</span>`;
}
function submitInquiry(e){
  e.preventDefault();
  const v=id=>document.getElementById(id).value.trim(), err=document.getElementById("f-err");
  if(!v("f-name")){ err.textContent=L("Vul uw naam in.","Please enter your name."); document.getElementById("f-name").focus(); return; }
  if(!v("f-mail")&&!v("f-tel")){ err.textContent=L("Vul een e-mailadres of telefoonnummer in, zodat we u kunnen antwoorden.","Please enter an email address or phone number so we can reply."); document.getElementById("f-mail").focus(); return; }
  if(v("f-mail")&&!/^\S+@\S+\.\S+$/.test(v("f-mail"))){ err.textContent=L("Dit e-mailadres lijkt niet compleet.","This email address looks incomplete."); document.getElementById("f-mail").focus(); return; }
  err.textContent="";
  const ty=document.getElementById("f-type").value;
  const lines=[`${L("Aanvraag","Enquiry")}: ${L(TYPES[ty][0],TYPES[ty][1])}`, S.inquiry.works.length?`${L("Werken","Works")}: ${S.inquiry.works.map(id=>`${title(id)} (Cat. ${id})`).join(", ")}`:null, `${L("Naam","Name")}: ${v("f-name")}`, v("f-place")?`${L("Woonplaats","Town")}: ${v("f-place")}`:null, v("f-mail")?`E-mail: ${v("f-mail")}`:null, v("f-tel")?`${L("Telefoon","Phone")}: ${v("f-tel")}`:null, v("f-msg")?`\n${v("f-msg")}`:null].filter(Boolean).join("\n");
  const link=wa(lines);
  document.getElementById("formWrap").innerHTML = `<div class="ready">
    <div class="label">${L("Uw aanvraag staat klaar","Your enquiry is ready")}</div>
    <p>${link?L(`Verstuur hem via WhatsApp naar ${firstName}. U krijgt per omgaande antwoord.`,`Send it to ${firstName} on WhatsApp. You will receive a reply right away.`):L("Kopieer de tekst en stuur hem naar ons.","Copy the text and send it to us.")} ${L("Bellen kan ook:","You can also call:")} <span class="num sel">${esc(SITE.contact.tel)}</span>.</p>
    <pre id="inqText">${esc(lines)}</pre>
    <div class="row2">${link?`<a class="btn" href="${link}" target="_blank" rel="noopener">${L("Verstuur via WhatsApp","Send via WhatsApp")}</a>`:""}<button class="btn ${link?"ghost":""}" type="button" id="copyInq">${L("Kopieer aanvraag","Copy enquiry")}</button></div>
    ${SITE.contact.email?`<p class="muted" style="font-size:14px">${L("Liever per e-mail? Stuur de tekst naar","Prefer email? Send the text to")} ${mailLink(L("Aanvraag","Enquiry"))}.</p>`:""}
    <button type="button" class="savetext" id="editInq">← ${L("Aanvraag aanpassen","Edit enquiry")}</button>
  </div>`;
}

const vAbout = () => `
  <div class="page-head"><div class="wrap split top-al">
    <div>
      <div class="label">${L("De kunstenaar","The artist")}</div>
      <h1 class="display" style="margin-top:14px">${L("Over Nanny","About Nanny")}</h1>
      <p class="lead">${L("Nanny Vriens-Koudenburg (1939–2024) was een Nederlandse beeldend kunstenaar met een diep intuïtieve hand. In ruim dertig jaar maakte ze meer dan driehonderd expressieve werken.","Nanny Vriens-Koudenburg (1939–2024) was a Dutch visual artist with a deeply intuitive hand. Over more than thirty years she created over three hundred expressive works.")}</p>
    </div>
    <figure style="margin:0;max-width:380px;justify-self:end;width:100%"><img src="img/portret.jpg" alt="${L("Portret van Nanny Vriens-Koudenburg","Portrait of Nanny Vriens-Koudenburg")}"></figure>
  </div></div>
  <section style="padding-top:24px"><div class="wrap split top-al">
    <div class="prose">
      <p>${L("Ze begon als keramiste. Na jaren met klei volgde ze schilderlessen, onder meer bij de stichting Algemene Kreatieve Vorming in Bilthoven. Eerst schilderde ze vooral met waterverf, daarna met gemengde technieken zoals inkt en krijt. In haar latere jaren koos ze voor krachtige acryl, op papier en op doek.","She began as a ceramicist. After years of working with clay she took painting lessons, including at the Algemene Kreatieve Vorming foundation in Bilthoven. At first she painted mainly in watercolour, then in mixed techniques such as ink and chalk. In her later years she turned to bold acrylics, on paper and on canvas.")}</p>
      <p>${L("Haar werk beweegt tussen abstractie en figuratie en verkent verandering, herinnering, plaats en de menselijke ervaring. Een stadsgezicht kon een begin zijn, net als een landschap, een lichaam of een gemoedstoestand. Ze schilderde op instinct en met emotionele eerlijkheid, bij voorkeur op groot formaat en in primaire kleuren.","Her work moves between abstraction and figuration, exploring transformation, memory, place and the human experience. A cityscape could be a beginning, as could a landscape, a body or a state of mind. She painted with instinct and emotional honesty, preferably on a large scale and in primary colours.")}</p>
      <p>${L("Onder de naam Modern Art Lease &amp; Sale bracht ze haar werk zelf naar kantoren en praktijken. Haar laatste werk,","Under the name Modern Art Lease &amp; Sale she placed her own work in offices and practices. Her final work,")} <a href="#werk-071"><span class="it">Death Valley National Park, USA</span></a>${L(", sluit een krachtige nalatenschap af: een die nog altijd ontroert en inspireert.",", closes a powerful legacy: one that continues to move and inspire.")}</p>
      <figure style="margin:20px 0 0"><img src="img/atelier.jpg" alt="${L("Nanny in haar atelier","Nanny in her studio")}" loading="lazy"><figcaption class="cap">${L("In het atelier, met","In the studio, with")} <a href="#werk-057"><span class="it">De Tram</span></a> ${L("op de ezel.","on the easel.")}</figcaption></figure>
    </div>
    <div style="display:grid;gap:40px">
      <div><div class="label" style="margin-bottom:10px">${L("Tentoonstellingen, een selectie","Exhibitions, a selection")}</div>
      <ul class="list">
        <li><span>Expeditie, Kunstuitleen Utrecht</span><span class="num">2008</span></li>
        <li><span>Paviljoen Woudschoten</span><span>Zeist</span></li>
        <li><span>Veldhoven Interieurs</span><span>Bilthoven</span></li>
        <li><span>${L("Openbare Bibliotheek","Public Library")}</span><span></span></li>
      </ul></div>
      <div><div class="label" style="margin-bottom:10px">${L("Haar werk hing onder meer bij","Her work hung at, among others")}</div>
      <ul class="list"><li><span>Grontmij</span><span>${L("Kantoor","Office")}</span></li><li><span>Fortis Bank</span><span>${L("Kantoor","Office")}</span></li><li><span>Ribo Investments</span><span>${L("Kantoor","Office")}</span></li><li><span>Huisartsenpraktijk De Paltz</span><span>${L("Praktijk","Practice")}</span></li></ul></div>
    </div>
  </div></section>`;

