const vNotFound = () => `<div class="page-head"><div class="wrap"><h1 class="display">${L("Niet gevonden","Not found")}</h1><p class="lead">${L("Dit werk of deze pagina bestaat niet.","This work or page does not exist.")}</p><div style="margin-top:28px"><a class="btn" href="#collectie">${L("Naar de collectie","Go to the collection")}</a></div></div></div>`;

/* ---------- router ---------- */
const app=document.getElementById("app");
let current="";
function setMenu(open){ const m=document.getElementById("menu"); m.hidden=!open; document.body.classList.toggle("menu-open",open); document.getElementById("menuBtn").setAttribute("aria-expanded",open); }
function route(keepScroll){
  const h=(location.hash||"").slice(1) || (window.PRESET||"");
  if(current==="collectie") S.scroll.collectie=window.scrollY;
  let html, after=null;
  if(!h||h==="home") html=vHome();
  else if(h==="collectie"){ html=vCollection(); after=()=>{ layoutGrid(); if(S.scroll.collectie) requestAnimationFrame(()=>window.scrollTo(0,S.scroll.collectie)); }; }
  else if(h.startsWith("werk-")) html=vDetail(h.slice(5));
  else if(h==="vind"){ html=vFind(); after=layoutFind; }
  else if(h==="over") html=vAbout();
  else if(h==="aankoop") html=vBuy();
  else if(h==="interieur") html=vDesigners();
  else if(h==="bewaard"){ html=vSaved(); after=layoutSaved; }
  else if(h==="contact"){ html=vContact(); after=renderPicked; }
  else if(h==="voorwaarden") html=vTerms();
  else if(h==="privacy") html=vPrivacy();
  else html=vNotFound();
  app.innerHTML=`<div class="view-enter">${html}</div>`;
  current=h.startsWith("werk-")?"werk":(h||"home");
  document.querySelectorAll(".nav a").forEach(a=>a.setAttribute("aria-current", a.dataset.r===current?"page":"false"));
  setMenu(false);
  if(h!=="collectie"&&!keepScroll) window.scrollTo(0,0);
  if(after) after();
  syncSaved();
  const id=h.startsWith("werk-")?h.slice(5):null;
  document.title = id&&byId[id] ? `${title(id)} · Nanny Vriens-Koudenburg` : "Nanny Vriens-Koudenburg";
  document.body.classList.toggle("has-mbar", !!id);
}
addEventListener("hashchange",()=>route());

/* ---------- interactie ---------- */
document.addEventListener("click",e=>{
  const t=e.target;
  if(t.closest("#langBtn")){ lang = lang==="en"?"nl":"en"; try{localStorage.setItem("nv-lang",lang);}catch(_){} chrome(); const y=scrollY; route(true); scrollTo(0,y); return; }
  if(t.closest("#menuBtn")){ setMenu(document.getElementById("menu").hidden); return; }
  if(t.closest("#menu a")){ setMenu(false); }
  const fo=t.closest("[data-find]"); if(fo){ S.find[fo.dataset.find]=fo.dataset.v; S.find.step++; route(); return; }
  if(t.closest("#findBack")){ S.find.step=Math.max(0,S.find.step-1); route(); return; }
  if(t.closest("#findReset")){ S.find={step:0,ruimte:null,sfeer:null,kleur:null}; route(); return; }
  const sv=t.closest("[data-save]"); if(sv){ e.preventDefault(); toggleSave(sv.dataset.save); if(current==="bewaard") layoutSaved(); return; }
  const th=t.closest("[data-theme-link]"); if(th){ S.f={thema:th.dataset.themeLink,kleur:null,ori:null,tweeluik:false}; S.q=""; S.scroll.collectie=0; if(location.hash==="#collectie"){ e.preventDefault(); route(); } return; }
  const iq=t.closest("[data-inquire]"); if(iq){ S.inquiry={works:[iq.dataset.inquire],type:iq.dataset.inquireType||"buy"}; return; }
  const iqs=t.closest("[data-inquire-saved]"); if(iqs){ S.inquiry={works:[...saved],type:iqs.dataset.inquireSaved}; return; }
  const iqt=t.closest("[data-inquire-type]"); if(iqt){ S.inquiry={works:S.inquiry.works,type:iqt.dataset.inquireType}; return; }
  const fb=t.closest("[data-f]"); if(fb){ const k=fb.dataset.f; if(k==="tweeluik") S.f.tweeluik=!S.f.tweeluik; else S.f[k]=S.f[k]===fb.dataset.v?null:fb.dataset.v; refreshFilters(); return; }
  if(t.closest("#clearF")||t.closest("#clearF2")){ S.f={thema:null,kleur:null,ori:null,tweeluik:false}; S.q=""; refreshFilters(); return; }
  if(t.closest("#ftoggle")){ S.filtersOpen=!S.filtersOpen; document.getElementById("filters").classList.toggle("open",S.filtersOpen); t.closest("#ftoggle").setAttribute("aria-expanded",S.filtersOpen); return; }
  const up=t.closest("[data-unpick]"); if(up){ S.inquiry.works=S.inquiry.works.filter(x=>x!==up.dataset.unpick); renderPicked(); return; }
  if(t.closest("#stage")){ openLB(location.hash.slice(6)); return; }
  if(t.closest("#copyInq")){ const el=document.getElementById("inqText"); const fallback=()=>{const r=document.createRange();r.selectNodeContents(el);const s=getSelection();s.removeAllRanges();s.addRange(r);toast(L("Tekst geselecteerd. Kopieer met Cmd/Ctrl+C.","Text selected. Copy with Cmd/Ctrl+C."));}; try{ navigator.clipboard.writeText(el.textContent).then(()=>toast(L("Aanvraag gekopieerd","Enquiry copied")),fallback); }catch(_){ fallback(); } return; }
  if(t.closest("#editInq")){ route(); return; }
});
document.addEventListener("input",e=>{ if(e.target.id==="q"){ S.q=e.target.value; layoutGrid(); } });
document.addEventListener("change",e=>{ if(e.target.id==="sort"){ S.sort=e.target.value; layoutGrid(); } });
document.addEventListener("submit",e=>{ if(e.target.id==="inqForm") submitInquiry(e); });
document.addEventListener("keydown",e=>{ if(e.target.id==="stage"&&(e.key==="Enter"||e.key===" ")){ e.preventDefault(); openLB(location.hash.slice(6)); } if(e.key==="Escape"&&!document.getElementById("menu").hidden) setMenu(false); });
function refreshFilters(){ const y=scrollY; S.scroll.collectie=0; app.innerHTML=`<div>${vCollection()}</div>`; layoutGrid(); scrollTo(0,y); syncSaved(); }
let rt; new ResizeObserver(()=>{ clearTimeout(rt); rt=setTimeout(()=>{ if(current==="collectie") layoutGrid(); if(current==="bewaard") layoutSaved(); if(current==="vind") layoutFind(); },120); }).observe(document.body);
addEventListener("scroll",()=>document.getElementById("top").classList.toggle("scrolled",scrollY>8),{passive:true});

/* ---------- vergroting ---------- */
let lbEl=null, lbId=null;
function openLB(id){
  lbId=id; const list=S.list.includes(id)?S.list:WORKS.map(w=>w.id);
  lbEl=document.createElement("div"); lbEl.className="lb"; lbEl.setAttribute("role","dialog"); lbEl.setAttribute("aria-label",L("Vergroting","Enlarged view"));
  lbEl.innerHTML=`<div class="frame"><img alt=""></div><button class="x">${L("Sluiten","Close")}</button><button class="pv" aria-label="${L("Vorig werk","Previous work")}"><svg viewBox="0 0 28 28"><path d="M17 5 8 14l9 9" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></button><button class="nx" aria-label="${L("Volgend werk","Next work")}"><svg viewBox="0 0 28 28"><path d="m11 5 9 9-9 9" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></button><div class="lbcap"></div>`;
  document.body.appendChild(lbEl); document.body.style.overflow="hidden";
  const img=lbEl.querySelector("img"), frame=lbEl.querySelector(".frame");
  const show=i=>{ lbId=i; img.src=LG(i); img.alt=title(i); lbEl.querySelector(".lbcap").textContent=`${title(i)} · Cat. ${i} · ${L("Klik om in te zoomen","Click to zoom")}`; lbEl.classList.remove("zoomed"); img.style.transformOrigin="center"; };
  const step=d=>{ const i=list.indexOf(lbId); show(list[(i+d+list.length)%list.length]); };
  show(id);
  frame.addEventListener("click",ev=>{ const r=img.getBoundingClientRect(); img.style.transformOrigin=`${((ev.clientX-r.left)/r.width*100).toFixed(1)}% ${((ev.clientY-r.top)/r.height*100).toFixed(1)}%`; lbEl.classList.toggle("zoomed"); });
  frame.addEventListener("mousemove",ev=>{ if(!lbEl.classList.contains("zoomed")) return; const r=frame.getBoundingClientRect(); img.style.transformOrigin=`${((ev.clientX-r.left)/r.width*100).toFixed(1)}% ${((ev.clientY-r.top)/r.height*100).toFixed(1)}%`; });
  lbEl.querySelector(".x").onclick=closeLB; lbEl.querySelector(".pv").onclick=()=>step(-1); lbEl.querySelector(".nx").onclick=()=>step(1);
  lbEl.addEventListener("click",ev=>{ if(ev.target===lbEl) closeLB(); });
  lbEl._key=ev=>{ if(ev.key==="Escape") closeLB(); if(ev.key==="ArrowLeft") step(-1); if(ev.key==="ArrowRight") step(1); };
  document.addEventListener("keydown",lbEl._key); lbEl.querySelector(".x").focus();
}
function closeLB(){ if(!lbEl) return; document.removeEventListener("keydown",lbEl._key); lbEl.remove(); lbEl=null; document.body.style.overflow=""; if(lbId&&location.hash!=="#werk-"+lbId) location.hash="werk-"+lbId; }

chrome();
route();
